                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


--
-- Name: add_audit_columns(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_audit_columns(tbl text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS created_at timestamptz DEFAULT now()', tbl);
    EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now()', tbl);
    EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS deleted_at timestamptz', tbl);
    EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS created_by uuid DEFAULT auth.uid()', tbl);
    EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS updated_by uuid', tbl);
END;
$$;


--
-- Name: fn_audit_gxp_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_gxp_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    old_data jsonb;
    new_data jsonb;
    user_uid uuid;
    record_id text;
BEGIN
    -- Captura o usuário logado (se houver)
    user_uid := auth.uid();
    
    -- Lógica de Extração Segura (Via JSONB para evitar erro de coluna inexistente)
    IF (TG_OP = 'DELETE') THEN
        old_data := to_jsonb(OLD);
        new_data := null;
        -- Tenta pegar 'id', se não tiver, tenta combinação de chaves ou fallback
        record_id := COALESCE(
            old_data->>'id', 
            (old_data->>'role_id') || ' | ' || (old_data->>'permission_slug'), -- Para app_role_permissions
            'PK_COMPOSTA'
        );
        
    ELSIF (TG_OP = 'INSERT') THEN
        old_data := null;
        new_data := to_jsonb(NEW);
        record_id := COALESCE(
            new_data->>'id', 
            (new_data->>'role_id') || ' | ' || (new_data->>'permission_slug'),
            'PK_COMPOSTA'
        );
        
    ELSIF (TG_OP = 'UPDATE') THEN
        old_data := to_jsonb(OLD);
        new_data := to_jsonb(NEW);
        
        -- Otimização: Se nada mudou, não audita
        IF old_data = new_data THEN 
            RETURN NEW; 
        END IF;
        
        record_id := COALESCE(
            new_data->>'id', 
            old_data->>'id', 
            'PK_COMPOSTA'
        );
    END IF;

    -- Inserção no Log
        tabela_afetada, 
        registro_id, 
        operacao, 
        usuario_id, 
        dados_anteriores, 
        dados_novos
    )
    VALUES (
        TG_TABLE_NAME::text, 
        record_id, 
        TG_OP, 
        user_uid, 
        old_data, 
        new_data
    );

    RETURN NEW;
END;
$$;


--
-- Name: fn_audit_log_automatico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_log_automatico() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_old_data jsonb;
  v_new_data jsonb;
  v_user_id uuid;
  v_registro_id text;
  v_ip_request text;
BEGIN
  v_user_id := auth.uid();
  
  BEGIN
    v_ip_request := current_setting('request.headers', true)::json->>'x-forwarded-for';
  EXCEPTION WHEN OTHERS THEN
    v_ip_request := null;
  END;

  IF (TG_OP = 'INSERT') THEN
    v_old_data := null;
    v_new_data := to_jsonb(NEW);
    v_registro_id := NEW.id::text;
  ELSIF (TG_OP = 'UPDATE') THEN
    v_old_data := to_jsonb(OLD);
    v_new_data := to_jsonb(NEW);
    v_registro_id := NEW.id::text;
    
    IF v_old_data = v_new_data THEN
        RETURN NEW;
    END IF;
  ELSIF (TG_OP = 'DELETE') THEN
    v_old_data := to_jsonb(OLD);
    v_new_data := null;
    v_registro_id := OLD.id::text;
  END IF;

    tabela_afetada,
    registro_id,
    operacao,
    usuario_id,
    dados_anteriores,
    dados_novos,
    ip_origem,
    data_evento
  ) VALUES (
    TG_TABLE_NAME::text,
    v_registro_id,
    TG_OP,
    v_user_id,
    v_old_data,
    v_new_data,
    v_ip_request,
    now()
  );

  RETURN NEW;
END;
$$;


