--
-- Name: fn_enforce_rdc429_porcao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_enforce_rdc429_porcao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_porcao_ref numeric;
BEGIN
  -- Só executa a verificação se tivermos a Categoria ANVISA e o Peso da Embalagem definidos
  IF NEW.anvisa_categoria_id IS NOT NULL AND NEW.peso_embalagem_g IS NOT NULL AND NEW.peso_embalagem_g > 0 THEN
     
     -- Busca a "Porção de Referência" na tabela oficial da ANVISA
     SELECT porcao_referencia_g_ml INTO v_porcao_ref
     FROM public.anvisa_categorias
     WHERE id = NEW.anvisa_categoria_id;

     -- Aplica a Regra da RDC 429 (Art. 8º):
     IF v_porcao_ref IS NOT NULL AND v_porcao_ref > 0 THEN
        -- REGRA: Se a quantidade total for menor ou igual a 2 vezes a porção de referência...
        IF NEW.peso_embalagem_g <= (2 * v_porcao_ref) THEN
           -- ... a porção declarada DEVE SER a embalagem inteira (Conceito de Embalagem Individual)
           -- O banco sobrescreve qualquer valor enviado pelo frontend.
           NEW.porcao_final_g_ml := NEW.peso_embalagem_g;
        ELSE
           -- CASO CONTRÁRIO (Embalagem Familiar/Food Service):
           -- Mantém a porção de referência oficial da categoria.
           -- Isso impede que o usuário declare porções fora do padrão (ex: "fatia fina" de 20g se a norma pede 50g).
           NEW.porcao_final_g_ml := v_porcao_ref;
        END IF;
     END IF;
     
  END IF;

  RETURN NEW;
END;
$$;


