$$;


--
-- Name: fn_gerar_lote_interno_automatico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_gerar_lote_interno_automatico() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    data_hoje text;
    fornecedor_hash text;
BEGIN
    -- Verifica se o lote veio vazio ou nulo
    IF NEW.codigo_lote_fornecedor IS NULL OR TRIM(NEW.codigo_lote_fornecedor) = '' THEN
        
        -- Formata a data atual: YYYYMMDD (Ex: 20251228)
        data_hoje := to_char(now(), 'YYYYMMDD');
        
        -- Pega os primeiros 4 dígitos do ID do fornecedor para garantir unicidade sem ficar gigante
        -- Se não tiver fornecedor (o que seria um erro), usa '0000'
        IF NEW.fornecedor_id IS NOT NULL THEN
            fornecedor_hash := substring(NEW.fornecedor_id::text, 1, 4);
        ELSE
            fornecedor_hash := '0000'; 
        END IF;

        -- GERA O CÓDIGO FINAL: INT-20251228-A1B2
        NEW.codigo_lote_fornecedor := 'INT-' || data_hoje || '-' || fornecedor_hash || '-' || substring(md5(random()::text), 1, 3);
        
        -- Marca como lote interno para relatórios
        NEW.is_lote_interno := true;
        
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_gerar_placeholders_ged_fornecedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_gerar_placeholders_ged_fornecedor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    cat_name TEXT;
    doc_record JSONB;
    doc_name TEXT;
    target_pasta_id UUID;
    full_target_name TEXT;
    v_old_razao_social TEXT;
    v_new_razao_social TEXT;
BEGIN
    -- Lógica de Renomeação (Caso mude a Razão Social)
    IF TG_OP = 'UPDATE' AND OLD.razao_social <> NEW.razao_social THEN
        v_old_razao_social := OLD.razao_social;
        v_new_razao_social := NEW.razao_social;
        
        -- Atualiza os nomes de arquivos vinculados a esta entidade_id
        UPDATE public.documentos_arquivos
        SET nome_arquivo = REPLACE(nome_arquivo, '[' || v_old_razao_social || ']', '[' || v_new_razao_social || ']')
        WHERE entidade_id = NEW.id
          AND nome_arquivo ILIKE '%[' || v_old_razao_social || ']%';
    END IF;

    -- Lógica de Geração de Placeholders (Novas Categorias)
    -- Iterar sobre categorias_compras (Level 1)
    IF NEW.categorias_compras IS NOT NULL THEN
        FOREACH cat_name IN ARRAY NEW.categorias_compras
        LOOP
            -- Buscar configurações da categoria
            FOR doc_record IN 
                SELECT unnest(documentos_obrigatorios) 
                FROM public.categorias_config 
                WHERE nome = cat_name 
                  AND cliente_id = NEW.cliente_id
                  AND deleted_at IS NULL
            LOOP
                doc_name := doc_record->>'nome';
                target_pasta_id := (doc_record->>'ged_pasta_id')::UUID;
                
                -- Se não tiver pasta específica, usa a pasta raiz do fornecedor (se houver)
                IF target_pasta_id IS NULL THEN
                    target_pasta_id := NEW.pasta_documentos_id;
                END IF;

                IF target_pasta_id IS NOT NULL AND doc_name IS NOT NULL THEN
                    full_target_name := '[' || NEW.razao_social || '] ' || doc_name;

                    -- Inserir placeholder se não existir (baseado em entidade_id E nome)
                    -- Usamos um check para evitar duplicatas sem depender de constraint UNIQUE
                    IF NOT EXISTS (
                        SELECT 1 FROM public.documentos_arquivos 
                        WHERE entidade_id = NEW.id 
                          AND (nome_arquivo = full_target_name OR nome_arquivo ILIKE '%' || doc_name)
                          AND pasta_id = target_pasta_id
                    ) THEN
                            pasta_id, 
                            nome_arquivo, 
                            entidade_id,
                            versao
                        )
                        VALUES (
                            target_pasta_id, 
                            full_target_name, 
                            NEW.id,
                            1
                        );
                    END IF;
                END IF;
            END LOOP;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_get_meus_clientes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_meus_clientes() RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Retorna IDs dos clientes baseados nas unidades que o usuário acessa
  RETURN ARRAY(
    SELECT DISTINCT c.id
    FROM public.clientes c
    JOIN public.cliente_unidades u ON u.cliente_id = c.id
    JOIN public.permissoes_usuario_unidade p ON p.unidade_id = u.id
    WHERE p.usuario_id = auth.uid()
  );
END;
$$;


