--
-- Name: fn_sync_comensais_uan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_comensais_uan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Se o número de comensais ou unidade mudou, força atualização de todos os dias vinculados
    IF OLD.comensais_estimados_dia <> NEW.comensais_estimados_dia OR OLD.unidade_id <> NEW.unidade_id THEN
        UPDATE public.cardapio_dias_uan 
        SET fator_multiplicador = fator_multiplicador 
        WHERE cardapio_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_sync_producao_pmp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_producao_pmp() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_unidade_id UUID;
    v_periodo_id UUID;
    v_mes_ano TEXT;
    v_data_inicio DATE;
    v_data_fim DATE;
    v_data_necessidade DATE;
BEGIN
    -- Obter unidade e data da ordem de produção
    SELECT unidade_id, data_prevista INTO v_unidade_id, v_data_necessidade
    FROM public.producao_ordens 
    WHERE id = NEW.ordem_id;

    IF v_data_necessidade IS NULL THEN 
        v_data_necessidade := CURRENT_DATE;
    END IF;

    v_mes_ano := to_char(v_data_necessidade, 'YYYY-MM');
    v_data_inicio := date_trunc('month', v_data_necessidade)::date;
    v_data_fim := (date_trunc('month', v_data_necessidade) + interval '1 month' - interval '1 day')::date;

    -- Upsert do Mes no PMP
    -- Alterado para usar ON CONFLICT (unidade_id, data_inicio, data_fim) 
    -- Assumindo que existe uma constraint unique ou índice único para esses 3 campos.
    VALUES (v_unidade_id, 'Planejamento ' || v_mes_ano, 'MENSAL', v_data_inicio, v_data_fim, 'APROVADO')
    ON CONFLICT (unidade_id, data_inicio, data_fim) DO UPDATE SET updated_at = now()
    RETURNING id INTO v_periodo_id;

    -- Upsert da Demanda (PCP usa receita_id)
    -- CORREÇÃO: NEW.quantidade -> NEW.quantidade_planejada
    VALUES (v_periodo_id, 'ORDEM_SERVICO', NEW.id, NEW.receita_id, v_data_necessidade, NEW.quantidade_planejada, 'UN')
    ON CONFLICT (origem_id) DO UPDATE SET 
        quantidade_planejada = EXCLUDED.quantidade_planejada,
        data_necessidade = EXCLUDED.data_necessidade,
        receita_id = EXCLUDED.receita_id;

    RETURN NEW;
END;
$$;


--
-- Name: fn_sync_uan_cardapio_pmp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_uan_cardapio_pmp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_unidade_id UUID;
    v_periodo_id UUID;
    v_mes_ano TEXT;
    v_data_inicio DATE;
    v_data_fim DATE;
    v_comensais INTEGER;
BEGIN
    -- Obter unidade e comensais do cardápio pai
    SELECT unidade_id, comensais_estimados_dia INTO v_unidade_id, v_comensais
    FROM public.cardapios_uan 
    WHERE id = NEW.cardapio_id;

    -- Se não houver unidade_id, não sincroniza (evita falha na constraint do PMP)
    IF v_unidade_id IS NULL THEN
        RETURN NEW;
    END IF;

    v_mes_ano := to_char(NEW.data_consumo, 'YYYY-MM');
    v_data_inicio := date_trunc('month', NEW.data_consumo)::date;
    v_data_fim := (date_trunc('month', NEW.data_consumo) + interval '1 month' - interval '1 day')::date;

    -- Upsert do Mes no PMP
    VALUES (v_unidade_id, 'Planejamento ' || v_mes_ano, 'MENSAL', v_data_inicio, v_data_fim, 'APROVADO')
    ON CONFLICT (unidade_id, data_inicio, data_fim) DO UPDATE SET updated_at = now()
    RETURNING id INTO v_periodo_id;

    -- Upsert da Demanda
    VALUES (v_periodo_id, 'CARDAPIO_UAN', NEW.id, NEW.ficha_uan_id, NEW.data_consumo, (v_comensais * NEW.fator_multiplicador), 'UN')
    ON CONFLICT (origem_id) DO UPDATE SET 
        pmp_periodo_id = EXCLUDED.pmp_periodo_id,
        quantidade_planejada = EXCLUDED.quantidade_planejada,
        data_necessidade = EXCLUDED.data_necessidade,
        ficha_uan_id = EXCLUDED.ficha_uan_id;

    RETURN NEW;
END;
$$;


