--
-- Name: gerar_requisicao_producao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gerar_requisicao_producao(p_ordem_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_item RECORD;
BEGIN
    -- Limpar requisições existentes para esta ordem
    DELETE FROM public.producao_requisicoes WHERE ordem_id = p_ordem_id;

    -- 1. Processar Receitas Industriais (receita_id)
    FOR v_item IN 
        SELECT 
            poi.receita_id,
            poi.quantidade_planejada,
            poi.setor_producao_id
        FROM public.producao_ordens_itens poi
        WHERE poi.ordem_id = p_ordem_id AND poi.receita_id IS NOT NULL
    LOOP
            ordem_id,
            ingrediente_id,
            qtd_necessaria_g,
            status
        )
        SELECT 
            p_ordem_id,
            cr.item_id,
            (v_item.quantidade_planejada / r.rendimento_total_g) * cr.peso_bruto_g,
            'PENDENTE'
        FROM public.composicao_receitas cr
        JOIN public.receitas r ON r.id = cr.receita_id
        WHERE cr.receita_id = v_item.receita_id AND cr.item_type = 'ingrediente';
    END LOOP;

    -- 2. Processar Fichas Técnicas UAN (ficha_uan_id)
    FOR v_item IN 
        SELECT 
            poi.ficha_uan_id,
            poi.quantidade_planejada,
            poi.setor_producao_id
        FROM public.producao_ordens_itens poi
        WHERE poi.ordem_id = p_ordem_id AND poi.ficha_uan_id IS NOT NULL
    LOOP
            ordem_id,
            ingrediente_id,
            qtd_necessaria_g,
            status
        )
        SELECT 
            p_ordem_id,
            cfu.ingrediente_id,
            (v_item.quantidade_planejada / NULLIF(ftu.rendimento_porcoes, 0)) * cfu.peso_bruto_g,
            'PENDENTE'
        FROM public.composicao_fichas_uan cfu
        JOIN public.fichas_tecnicas_uan ftu ON ftu.id = cfu.ficha_uan_id
        WHERE cfu.ficha_uan_id = v_item.ficha_uan_id;
    END LOOP;

END;
$$;


--
-- Name: get_accessible_unit_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_unit_ids() RETURNS TABLE(unit_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  current_user_role TEXT;
  current_company_id UUID;
  current_user_email TEXT;
BEGIN
  -- Busca dados do perfil atual
  SELECT role, company_id, email INTO current_user_role, current_company_id, current_user_email
  FROM public.profiles
  WHERE id = auth.uid();

  -- REGRA 1: SUPER ADMIN GLOBAL (Seu e-mail ou role)
  -- Para garantir, chumbamos seu e-mail como "god mode" além da role
  IF current_user_role = 'super_admin' OR current_user_email = 'jaugustolt1998@gmail.com' THEN
    RETURN QUERY SELECT id FROM public.units; -- Retorna TODAS as unidades do sistema
    RETURN;
  END IF;

  -- REGRA 2: DONO DA EMPRESA (Vê todas as unidades da empresa dele)
  IF current_user_role = 'company_owner' THEN
    RETURN QUERY SELECT id FROM public.units WHERE company_id = current_company_id;
    RETURN;
  END IF;

  -- REGRA 3: FUNCIONÁRIOS/GERENTES (Apenas unidades atribuídas explicitamente)
  RETURN QUERY 
    SELECT uu.unit_id 
    FROM public.user_units uu 
    WHERE uu.user_id = auth.uid();
END;
$$;


--
-- Name: get_my_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_org_id() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN (SELECT organization_id FROM profiles WHERE id = auth.uid());
END;
$$;


--
-- Name: get_user_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_permissions() RETURNS TABLE(permission_slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  current_user_id uuid;
BEGIN
  current_user_id := auth.uid();

  RETURN QUERY
  (
    -- Permissões herdadas do cargo
    SELECT DISTINCT arp.permission_slug
    FROM public.app_role_permissions arp
    JOIN public.app_user_memberships aum ON arp.role_id = aum.role_id
    WHERE aum.usuario_id = current_user_id
    AND aum.ativo = true
  )
  UNION
  (
    -- Permissões individuais (overrides)
    SELECT up.permission_slug
    FROM public.app_user_permissions up
    WHERE up.usuario_id = current_user_id
  );
END;
$$;


--
-- Name: handle_audit_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  old_data_json JSONB;
  new_data_json JSONB;
  op_type TEXT;
  record_uuid UUID;
  current_user_id UUID;
BEGIN
  -- Identifica o usuário logado (se for via API/Frontend)
  current_user_id := auth.uid();
  
  -- Define a operação e os dados
  IF (TG_OP = 'INSERT') THEN
    op_type := 'INSERT';
    old_data_json := null;
    new_data_json := to_jsonb(NEW);
    -- Tenta pegar o ID do registro (assume que a tabela tem coluna ID ou similar)
    record_uuid := COALESCE((to_jsonb(NEW) ->> 'id')::uuid, gen_random_uuid());
    
  ELSIF (TG_OP = 'UPDATE') THEN
    op_type := 'UPDATE';
    old_data_json := to_jsonb(OLD);
    new_data_json := to_jsonb(NEW);
    record_uuid := (to_jsonb(NEW) ->> 'id')::uuid;
    
    -- Se nada mudou, não registra (evita lixo no banco)
    IF old_data_json = new_data_json THEN
      RETURN NEW;
    END IF;

  ELSIF (TG_OP = 'DELETE') THEN
    op_type := 'DELETE';
    old_data_json := to_jsonb(OLD);
    new_data_json := null;
    record_uuid := (to_jsonb(OLD) ->> 'id')::uuid;
  END IF;

  -- Insere o Log com os nomes de colunas CORRETOS (Português)
    tabela_afetada,
    registro_id,
    operacao,
    dados_anteriores,
    dados_novos,
    usuario_id
  ) VALUES (
    TG_TABLE_NAME,
    record_uuid::text,
    op_type,
    old_data_json,
    new_data_json,
    current_user_id
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION
  WHEN OTHERS THEN
    -- Em caso de erro no log, não bloqueia a transação principal (melhor salvar o dado sem log do que travar tudo)
    RAISE WARNING 'Erro ao gerar log de auditoria: %', SQLERRM;
    RETURN COALESCE(NEW, OLD);
END;
$$;


