--
-- Name: registrar_producao(uuid, uuid, numeric, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_producao(p_cliente_id uuid, p_receita_id uuid, p_qtd_produzida numeric, p_data_validade date, p_lote_codigo text, p_responsavel_id uuid, p_insumos jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_producao_id uuid;
    v_versao_id uuid;
    v_item jsonb;
    v_saldo_atual numeric;
    v_lote_id_target uuid;
BEGIN
    -- Busca a versão mais recente aprovada para auditoria
    SELECT id INTO v_versao_id FROM public.receitas_versoes
    WHERE receita_id = p_receita_id
    ORDER BY versao DESC LIMIT 1;

    -- Cria o registro da Ordem de Produção
        cliente_id,
        receita_id,
        receita_versao_id,
        quantidade_produzida,
        codigo_lote_produto,
        data_validade,
        responsavel_id,
        status
    ) VALUES (
        p_cliente_id,
        p_receita_id,
        v_versao_id,
        p_qtd_produzida,
        p_lote_codigo,
        p_responsavel_id,
        'CONCLUIDO'
    ) RETURNING id INTO v_producao_id;

    -- Loop pelos insumos para dar baixa e registrar rastreio
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_insumos)
    LOOP
        v_lote_id_target := (v_item->>'lote_id')::uuid;

        -- Verifica saldo atual
        SELECT quantidade_atual INTO v_saldo_atual
        FROM public.estoque_lotes
        WHERE id = v_lote_id_target;

        -- Baixa no Estoque
        UPDATE public.estoque_lotes
        SET 
            quantidade_atual = quantidade_atual - (v_item->>'qtd_utilizada')::numeric,
            status_lote = CASE 
                WHEN (quantidade_atual - (v_item->>'qtd_utilizada')::numeric) <= 0.001 THEN 'ESGOTADO' 
                ELSE status_lote 
            END
        WHERE id = v_lote_id_target;

        -- Registro de Rastreabilidade (Fallback Inteligente de Colunas)
        BEGIN
                producao_id,
                lote_ingrediente_id, 
                quantidade_utilizada,
                unidade_medida
            ) VALUES (
                v_producao_id,
                v_lote_id_target,
                (v_item->>'qtd_utilizada')::numeric,
                COALESCE((v_item->>'unidade_medida'), 'UN')
            );
        EXCEPTION WHEN undefined_column THEN
            -- Se a coluna nova não existir, usa a antiga (Fase 1)
                producao_id,
                estoque_lote_id,
                quantidade_utilizada
            ) VALUES (
                v_producao_id,
                v_lote_id_target,
                (v_item->>'qtd_utilizada')::numeric
            );
        END;

        -- Registro de Movimentação (Kardex)
            lote_id,
            tipo_movimento,
            quantidade_movimentada,
            quantidade_nova,
            justificativa,
            responsavel_id
        ) VALUES (
            v_lote_id_target,
            'SAIDA_PRODUCAO',
            (v_item->>'qtd_utilizada')::numeric,
            v_saldo_atual - (v_item->>'qtd_utilizada')::numeric,
            'Produção OP: ' || p_lote_codigo,
            p_responsavel_id
        );

    END LOOP;

    RETURN jsonb_build_object('success', true, 'id', v_producao_id);

EXCEPTION WHEN OTHERS THEN
    RAISE; -- Repassa o erro para o frontend
END;
$$;


