--
-- Name: sync_admin_role_to_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_admin_role_to_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    admin_role_id uuid;
BEGIN
    -- Busca o ID do cargo Administrador
    SELECT id INTO admin_role_id FROM public.app_roles WHERE nome = 'Administrador' LIMIT 1;

    IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') THEN
        IF NEW.role_id = admin_role_id THEN
            -- Se for atribuído o cargo Administrador, atualiza o profile
            UPDATE public.profiles SET role = 'super_admin' WHERE id = NEW.usuario_id;
        END IF;
    ELSIF (TG_OP = 'DELETE') THEN
        -- Se deletar um vínculo, verifica se ainda existem outros vínculos de Administrador
        IF NOT EXISTS (
            SELECT 1 FROM public.app_user_memberships 
            WHERE usuario_id = OLD.usuario_id AND role_id = admin_role_id
        ) THEN
            -- Se não sobrou nenhum, remove o privilégio global
            -- UPDATE public.profiles SET role = NULL WHERE id = OLD.usuario_id;
            -- Comentado para evitar perda acidental de acesso se houver transição
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


