    rico_em_enxofre boolean DEFAULT false,
    CONSTRAINT fichas_tecnicas_uan_cor_predominante_check CHECK (((cor_predominante IS NULL) OR ((cor_predominante)::text = ANY ((ARRAY['Branco'::character varying, 'Marrom'::character varying, 'Verde'::character varying, 'Vermelho'::character varying, 'Amarelo'::character varying, 'Laranja'::character varying, 'Misto'::character varying])::text[])))),
    CONSTRAINT fichas_tecnicas_uan_metodo_coccao_check CHECK (((metodo_coccao IS NULL) OR ((metodo_coccao)::text = ANY ((ARRAY['Cru'::character varying, 'Cozido_Agua'::character varying, 'Cozido_Vapor'::character varying, 'Assado'::character varying, 'Grelhado'::character varying, 'Frito_Imersao'::character varying, 'Salteado'::character varying, 'Refogado'::character varying, 'Brasado'::character varying])::text[])))),
    CONSTRAINT fichas_tecnicas_uan_textura_principal_check CHECK (((textura_principal IS NULL) OR ((textura_principal)::text = ANY ((ARRAY['Crocante'::character varying, 'Macio'::character varying, 'Cremoso'::character varying, 'Firme'::character varying, 'Gelatinoso'::character varying, 'Líquido'::character varying])::text[]))))
);


