--
-- Name: gerencial_compras_kraljic_base; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gerencial_compras_kraljic_base AS
 WITH fornecedores_por_item AS (
         SELECT o.ingrediente_id,
            min(o.preco_por_kg_l) AS menor_preco,
            count(DISTINCT o.fornecedor_id) AS qtd_fornecedores,
            max(f.lead_time_dias) AS lead_time_max
           FROM (public.compras_orcamentos o
             JOIN public.fornecedores f ON ((o.fornecedor_id = f.id)))
          GROUP BY o.ingrediente_id
        ), estoque_por_item AS (
         SELECT estoque_lotes.ingrediente_id,
            sum(estoque_lotes.quantidade_atual_g_ml) AS total_estoque
           FROM public.estoque_lotes
          WHERE (estoque_lotes.quantidade_atual_g_ml > (0)::numeric)
          GROUP BY estoque_lotes.ingrediente_id
        ), demanda_cardapios AS (
         SELECT comp.ingrediente_id,
            sum((((comp.peso_bruto_g * COALESCE(dias.fator_multiplicador, (1)::numeric)) * (COALESCE(card.comensais_estimados_dia, 1))::numeric) / 1000.0)) AS demanda_mrp_kg
           FROM ((public.cardapio_dias_uan dias
             JOIN public.cardapios_uan card ON ((dias.cardapio_id = card.id)))
             JOIN public.composicao_fichas_uan comp ON ((dias.ficha_uan_id = comp.ficha_uan_id)))
          WHERE (dias.data_consumo >= CURRENT_DATE)
          GROUP BY comp.ingrediente_id
        ), demanda_producao AS (
         SELECT comp.ingrediente_id,
            sum(((comp.peso_bruto_g * COALESCE(itens.quantidade_planejada, (1)::numeric)) / 1000.0)) AS demanda_mrp_kg
           FROM ((public.producao_ordens_itens itens
             JOIN public.producao_ordens ordem ON ((itens.ordem_id = ordem.id)))
             JOIN public.composicao_fichas_uan comp ON ((itens.receita_id = comp.ficha_uan_id)))
          WHERE (ordem.data_prevista >= CURRENT_DATE)
          GROUP BY comp.ingrediente_id
        ), demanda_unificada AS (
         SELECT u.ingrediente_id,
            sum(u.demanda_mrp_kg) AS programacao_futura_kg
           FROM ( SELECT demanda_cardapios.ingrediente_id,
                    demanda_cardapios.demanda_mrp_kg
                   FROM demanda_cardapios
                UNION ALL
                 SELECT demanda_producao.ingrediente_id,
                    demanda_producao.demanda_mrp_kg
                   FROM demanda_producao) u
          GROUP BY u.ingrediente_id
        )
 SELECT i.id AS ingrediente_id,
    i.nome AS ingrediente_nome,
    i.grupo_id AS categoria_produto_id,
    i.uso_medio_diario,
    i.estoque_seguranca_perc,
    COALESCE(e.total_estoque, (0)::numeric) AS estoque_atual,
    COALESCE(f_info.menor_preco, (0)::numeric) AS custo_referencia,
    COALESCE(f_info.qtd_fornecedores, (0)::bigint) AS fornecedores_ativos,
    COALESCE(f_info.lead_time_max, 3) AS lead_time_considerado,
    COALESCE(mrp.programacao_futura_kg, (0)::numeric) AS demanda_programada_kg
   FROM (((public.ingredientes i
     LEFT JOIN fornecedores_por_item f_info ON ((i.id = f_info.ingrediente_id)))
     LEFT JOIN estoque_por_item e ON ((i.id = e.ingrediente_id)))
     LEFT JOIN demanda_unificada mrp ON ((i.id = mrp.ingrediente_id)));


