    assinatura_obrigatoria_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    prazo_limite timestamp with time zone,
    concluida_em timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT operacao_tarefas_prioridade_check CHECK ((prioridade = ANY (ARRAY['BAIXA'::text, 'MEDIA'::text, 'ALTA'::text, 'CRITICA'::text]))),
    CONSTRAINT operacao_tarefas_status_check CHECK ((status = ANY (ARRAY['A_FAZER'::text, 'EM_ANDAMENTO'::text, 'REVISAO'::text, 'CONCLUIDA'::text]))),
    CONSTRAINT operacao_tarefas_tipo_check CHECK ((tipo = ANY (ARRAY['POP'::text, 'MANUTENCAO'::text, 'PRODUCAO'::text, 'LIMPEZA'::text, 'AVULSA'::text])))
);


