    ordem_exibicao integer DEFAULT 0,
    fixo boolean DEFAULT false NOT NULL,
    fichas_fixas uuid[],
    CONSTRAINT chk_slot_min_max CHECK ((quantidade_min <= quantidade_max)),
    CONSTRAINT perfil_cardapio_slots_quantidade_max_check CHECK ((quantidade_max >= 1)),
    CONSTRAINT perfil_cardapio_slots_quantidade_min_check CHECK ((quantidade_min >= 0))
);


