--
-- Name: fornecedores Acesso Total Fornecedores; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso Total Fornecedores" ON public.fornecedores TO authenticated USING (true) WITH CHECK (true);


--
-- Name: fin_lancamentos Acesso aos Lancamentos; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso aos Lancamentos" ON public.fin_lancamentos USING ((transacao_id IN ( SELECT fin_transacoes.id
   FROM public.fin_transacoes
  WHERE (fin_transacoes.unidade_id IN ( SELECT permissoes_usuario_unidade.unidade_id
           FROM public.permissoes_usuario_unidade
          WHERE (permissoes_usuario_unidade.usuario_id = auth.uid()))))));


--
-- Name: producao_ordens_itens Acesso aos itens das ordens; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso aos itens das ordens" ON public.producao_ordens_itens USING ((ordem_id IN ( SELECT producao_ordens.id
   FROM public.producao_ordens
  WHERE (producao_ordens.unidade_id IN ( SELECT app_user_memberships.unidade_id
           FROM public.app_user_memberships
          WHERE (app_user_memberships.usuario_id = auth.uid()))))));


--
-- Name: fin_contas Acesso as Contas Financeiras; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso as Contas Financeiras" ON public.fin_contas USING ((cliente_id IN ( SELECT cu.cliente_id
   FROM (public.cliente_unidades cu
     JOIN public.app_user_memberships m ON ((m.unidade_id = cu.id)))
  WHERE (m.usuario_id = auth.uid()))));


--
-- Name: fin_transacoes Acesso as Transacoes Financeiras; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso as Transacoes Financeiras" ON public.fin_transacoes USING ((unidade_id IN ( SELECT permissoes_usuario_unidade.unidade_id
   FROM public.permissoes_usuario_unidade
  WHERE (permissoes_usuario_unidade.usuario_id = auth.uid()))));


--
-- Name: producao_ordens Acesso as ordens da unidade; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso as ordens da unidade" ON public.producao_ordens USING ((unidade_id IN ( SELECT app_user_memberships.unidade_id
   FROM public.app_user_memberships
  WHERE (app_user_memberships.usuario_id = auth.uid()))));


--
-- Name: ingrediente_alergenicos Acesso as relações de alergênicos permitidos; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso as relações de alergênicos permitidos" ON public.ingrediente_alergenicos USING ((ingrediente_id IN ( SELECT ingredientes.id
   FROM public.ingredientes
  WHERE (ingredientes.cliente_id IN ( SELECT cu.cliente_id
           FROM (public.app_user_memberships m
             JOIN public.cliente_unidades cu ON ((m.unidade_id = cu.id)))
          WHERE ((m.usuario_id = auth.uid()) AND (m.ativo = true)))))));


--
-- Name: producao_requisicoes Acesso as requisições das ordens; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso as requisições das ordens" ON public.producao_requisicoes USING ((ordem_id IN ( SELECT producao_ordens.id
   FROM public.producao_ordens
  WHERE (producao_ordens.unidade_id IN ( SELECT app_user_memberships.unidade_id
           FROM public.app_user_memberships
          WHERE (app_user_memberships.usuario_id = auth.uid()))))));


--
-- Name: producao_reservas_estoque Acesso as reservas de estoque; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso as reservas de estoque" ON public.producao_reservas_estoque USING ((requisicao_id IN ( SELECT r.id
   FROM (public.producao_requisicoes r
     JOIN public.producao_ordens o ON ((o.id = r.ordem_id)))
  WHERE (o.unidade_id IN ( SELECT app_user_memberships.unidade_id
           FROM public.app_user_memberships
          WHERE (app_user_memberships.usuario_id = auth.uid()))))));


--
-- Name: checklist_execucoes Acesso execucoes; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso execucoes" ON public.checklist_execucoes USING ((unidade_id = ANY (public.fn_get_minhas_unidades())));


--
-- Name: producao_ordens_legado Acesso por Cliente; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso por Cliente" ON public.producao_ordens_legado USING (true) WITH CHECK (true);


--
-- Name: producao_perdas Acesso por Unidade; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Acesso por Unidade" ON public.producao_perdas TO authenticated USING ((unidade_id IN ( SELECT m.unidade_id
   FROM public.app_user_memberships m
  WHERE (m.usuario_id = auth.uid())))) WITH CHECK ((unidade_id IN ( SELECT m.unidade_id
   FROM public.app_user_memberships m
  WHERE (m.usuario_id = auth.uid()))));


