CREATE POLICY "Acesso por cliente_id" ON public.ingredientes TO authenticated USING (((cliente_id IN ( SELECT cu.cliente_id
   FROM (public.app_user_memberships aum
     JOIN public.cliente_unidades cu ON ((cu.id = aum.unidade_id)))
  WHERE (aum.usuario_id = auth.uid()))) OR (cliente_id IS NULL)));


