20260301000000	{"-- ==========================================\r\n-- FASE 2: WMS, ESTOQUE E CHÃO DE FÁBRICA\r\n-- Sistema: NutriDev Manager GxP\r\n-- Objetivo: Conformidade RDC 216 e RDC 429\r\n-- ==========================================\r\n\r\n-- 1. Criação de Enums de Status\r\nCREATE TYPE status_lote_estoque AS ENUM ('QUARENTENA', 'APROVADO', 'REJEITADO', 'VENCIDO')","CREATE TYPE status_ordem_producao AS ENUM ('PENDENTE', 'EM_PREPARO', 'FINALIZADA', 'CANCELADA')","-- ==========================================\r\n-- MÓDULO 2: WMS E ESTOQUE\r\n-- ==========================================\r\n\r\n-- Tabela: Fornecedores\r\nCREATE TABLE IF NOT EXISTS public.fornecedores (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\r\n    razao_social TEXT NOT NULL,\r\n    nome_fantasia TEXT,\r\n    cnpj TEXT UNIQUE NOT NULL,\r\n    homologado_qualidade BOOLEAN DEFAULT FALSE,\r\n    created_at TIMESTAMPTZ DEFAULT NOW(),\r\n    updated_at TIMESTAMPTZ DEFAULT NOW()\r\n)","-- Tabela: Lotes de Estoque (Recebimento)\r\nCREATE TABLE IF NOT EXISTS public.lotes_estoque (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id) ON DELETE CASCADE,\r\n    ingrediente_id UUID NOT NULL REFERENCES public.ingredientes(id) ON DELETE RESTRICT,\r\n    fornecedor_id UUID NOT NULL REFERENCES public.fornecedores(id) ON DELETE RESTRICT,\r\n    numero_lote_fabricante TEXT NOT NULL,\r\n    nota_fiscal TEXT,\r\n    data_fabricacao DATE NOT NULL,\r\n    data_validade_rotulo DATE NOT NULL,\r\n    data_validade_interna DATE, -- Calculada/Ajustada pela Qualidade (Predição)\r\n    quantidade_inicial_g_ml NUMERIC NOT NULL CHECK (quantidade_inicial_g_ml > 0),\r\n    quantidade_atual_g_ml NUMERIC NOT NULL CHECK (quantidade_atual_g_ml >= 0),\r\n    status status_lote_estoque DEFAULT 'QUARENTENA',\r\n    created_at TIMESTAMPTZ DEFAULT NOW()\r\n)","-- ==========================================\r\n-- MÓDULO 3: PRODUÇÃO / CHÃO DE FÁBRICA\r\n-- ==========================================\r\n\r\n-- Tabela: Ordens de Produção (OP)\r\nCREATE TABLE IF NOT EXISTS public.ordens_producao (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id) ON DELETE CASCADE,\r\n    receita_id UUID NOT NULL REFERENCES public.receitas(id) ON DELETE RESTRICT,\r\n    receita_versao_utilizada INT NOT NULL, -- Puxado de receitas.versao_atual\r\n    status status_ordem_producao DEFAULT 'PENDENTE',\r\n    data_prevista_inicio TIMESTAMPTZ,\r\n    data_real_finalizacao TIMESTAMPTZ,\r\n    rendimento_esperado_g NUMERIC NOT NULL,\r\n    rendimento_realizado_g NUMERIC,\r\n    responsavel_id UUID REFERENCES auth.users(id),\r\n    created_at TIMESTAMPTZ DEFAULT NOW()\r\n)","-- Tabela: Apontamentos de Produção (Baixa de Múltiplos Lotes)\r\nCREATE TABLE IF NOT EXISTS public.apontamentos_producao (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    ordem_producao_id UUID NOT NULL REFERENCES public.ordens_producao(id) ON DELETE CASCADE,\r\n    lote_estoque_id UUID NOT NULL REFERENCES public.lotes_estoque(id) ON DELETE RESTRICT,\r\n    quantidade_utilizada_g_ml NUMERIC NOT NULL CHECK (quantidade_utilizada_g_ml > 0),\r\n    created_at TIMESTAMPTZ DEFAULT NOW()\r\n)","-- Tabela: Lotes Internos (Rastreabilidade e NutriPrint)\r\nCREATE TABLE IF NOT EXISTS public.lotes_internos (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id) ON DELETE CASCADE,\r\n    ordem_producao_id UUID NOT NULL UNIQUE REFERENCES public.ordens_producao(id) ON DELETE RESTRICT,\r\n    codigo_lote_interno TEXT UNIQUE NOT NULL,\r\n    data_fabricacao TIMESTAMPTZ NOT NULL DEFAULT NOW(),\r\n    data_validade TIMESTAMPTZ NOT NULL, -- O menor vencimento entre os insumos ou regra própria\r\n    created_at TIMESTAMPTZ DEFAULT NOW()\r\n)","-- ==========================================\r\n-- ROW LEVEL SECURITY (RLS) MULTI-TENANT\r\n-- ==========================================\r\n\r\nALTER TABLE public.fornecedores ENABLE ROW LEVEL SECURITY","ALTER TABLE public.lotes_estoque ENABLE ROW LEVEL SECURITY","ALTER TABLE public.ordens_producao ENABLE ROW LEVEL SECURITY","ALTER TABLE public.apontamentos_producao ENABLE ROW LEVEL SECURITY","ALTER TABLE public.lotes_internos ENABLE ROW LEVEL SECURITY","-- Exemplo RLS: Fornecedor (Baseado em Cliente)\r\nCREATE POLICY \\"Fornecedores Isolados por Cliente\\" ON public.fornecedores\r\n    FOR ALL\r\n    USING (cliente_id IN (\r\n        SELECT adm.cliente_id FROM public.app_roles adm\r\n        JOIN public.app_user_memberships m ON m.role_id = adm.id\r\n        WHERE m.usuario_id = auth.uid()\r\n    ))","-- Exemplo RLS: Lotes e Estoque (Baseado em Unidade)\r\nCREATE POLICY \\"Estoque Isolado por Unidade\\" ON public.lotes_estoque\r\n    FOR ALL\r\n    USING (unidade_id IN (\r\n        SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\r\n    ))","CREATE POLICY \\"Produção Isolada por Unidade\\" ON public.ordens_producao\r\n    FOR ALL\r\n    USING (unidade_id IN (\r\n        SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\r\n    ))","CREATE POLICY \\"Apontamentos da Produção Local\\" ON public.apontamentos_producao\r\n    FOR ALL\r\n    USING (ordem_producao_id IN (\r\n        SELECT id FROM public.ordens_producao WHERE unidade_id IN (\r\n            SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\r\n        )\r\n    ))","CREATE POLICY \\"Lotes Internos da Unidade\\" ON public.lotes_internos\r\n    FOR ALL\r\n    USING (unidade_id IN (\r\n        SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\r\n    ))"}	fase2_estoque_producao	\N	\N	\N
20260306195301	{"\nCREATE TABLE public.produtos_bombeiros (\n    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    nome TEXT NOT NULL,\n    descricao TEXT,\n    \n    -- Regras de Licenciamento (regras_sivisa.md)\n    data_emissao DATE NOT NULL,\n    data_validade DATE NOT NULL,\n    status_sivisa TEXT CHECK (status_sivisa IN ('Aprovado', 'Aguardando Vistoria', 'Exigência')) DEFAULT 'Aguardando Vistoria',\n\n    -- Trilha de Auditoria e Soft Delete (banco_de_dados.md)\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    created_by UUID REFERENCES auth.users(id),\n    updated_by UUID REFERENCES auth.users(id),\n    deleted_at TIMESTAMP WITH TIME ZONE\n);\n\n-- Index para otimização de consultas de soft delete\nCREATE INDEX idx_produtos_bombeiros_ativo ON public.produtos_bombeiros(id) WHERE deleted_at IS NULL;\n\n-- Trigger para auto-atualizar o updated_at\nCREATE OR REPLACE FUNCTION public.handle_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER on_produtos_bombeiros_updated\n    BEFORE UPDATE ON public.produtos_bombeiros\n    FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();\n\n-- Políticas RLS genéricas para demonstração (na prática seriam rigorosas)\nALTER TABLE public.produtos_bombeiros ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"Soft delete hide deleted records\\"\nON public.produtos_bombeiros FOR SELECT\nUSING (deleted_at IS NULL);\n"}	20260306193508_create_produtos_bombeiros	zezolas27@gmail.com	\N	\N
20260306200509	{"-- Permite INSERTs de usuários anonimos ou autenticados para viabilizar as constraints do banco sem bloqueio precoce por RLS\nCREATE POLICY \\"Allow public insert for testing constraints\\"\nON public.produtos_bombeiros FOR INSERT\nWITH CHECK (true);\n"}	20260306193508_rls_produtos_bombeiros	zezolas27@gmail.com	\N	\N
20260306201253	{"-- Injeção em lote para Tabela Receitas\nALTER TABLE public.receitas \nADD COLUMN IF NOT EXISTS created_by UUID REFERENCES auth.users(id) DEFAULT auth.uid(),\nADD COLUMN IF NOT EXISTS updated_by UUID REFERENCES auth.users(id),\nADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;\n\n-- Injeção em lote para Tabela Estoque_Lotes\nALTER TABLE public.estoque_lotes \nADD COLUMN IF NOT EXISTS updated_by UUID REFERENCES auth.users(id),\nADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\nADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;\n\n-- Injeção em lote para Tabela Ordens_Producao\nALTER TABLE public.ordens_producao \nADD COLUMN IF NOT EXISTS created_by UUID REFERENCES auth.users(id) DEFAULT auth.uid(),\nADD COLUMN IF NOT EXISTS created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\nADD COLUMN IF NOT EXISTS updated_by UUID REFERENCES auth.users(id),\nADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\nADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;\n\n-- Injeção em lote para Tabela Ingredientes\nALTER TABLE public.ingredientes \nADD COLUMN IF NOT EXISTS created_by UUID REFERENCES auth.users(id) DEFAULT auth.uid(),\nADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\nADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;\n\n-- Injeção em lote para Tabela Fornecedores\nALTER TABLE public.fornecedores \nADD COLUMN IF NOT EXISTS created_by UUID REFERENCES auth.users(id) DEFAULT auth.uid(),\nADD COLUMN IF NOT EXISTS updated_by UUID REFERENCES auth.users(id),\nADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\nADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;"}	20260306193508_audit_columns_patch	zezolas27@gmail.com	\N	\N
20260306201302	{"-- Configurando Trigger de Atualização Automática para as novas colunas updated_at\n\n-- Para ordens_producao\nCREATE TRIGGER on_ordens_producao_updated\n    BEFORE UPDATE ON public.ordens_producao\n    FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();\n\n-- Para estoque_lotes\nCREATE TRIGGER on_estoque_lotes_updated\n    BEFORE UPDATE ON public.estoque_lotes\n    FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();\n\n-- Para ingredientes\nCREATE TRIGGER on_ingredientes_updated\n    BEFORE UPDATE ON public.ingredientes\n    FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();\n\n-- Para fornecedores\nCREATE TRIGGER on_fornecedores_updated\n    BEFORE UPDATE ON public.fornecedores\n    FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();"}	20260306193508_audit_triggers_patch	zezolas27@gmail.com	\N	\N
