20260320170112	{"-- Migration: Add storage destination to producao_perdas\nALTER TABLE public.producao_perdas ADD COLUMN IF NOT EXISTS destino_id UUID;\nALTER TABLE public.producao_perdas ADD COLUMN IF NOT EXISTS tipo_destino VARCHAR(50);\nCOMMENT ON COLUMN public.producao_perdas.destino_id IS 'ID do local de estoque ou setor de produção onde a sobra foi armazenada.';\nCOMMENT ON COLUMN public.producao_perdas.tipo_destino IS 'Tipo do destino (LOCAL para cliente_locais_estoque, SETOR para cliente_setores_producao).';\n"}	add_destino_to_producao_perdas_v2	zezolas27@gmail.com	\N	\N
20260320170620	{"-- Migration: Complete producao_perdas table for leftovers tracking\nALTER TABLE public.producao_perdas \n  ADD COLUMN IF NOT EXISTS ingrediente_id UUID REFERENCES public.ingredientes(id),\n  ADD COLUMN IF NOT EXISTS item_ordem_id UUID REFERENCES public.producao_ordens_itens(id),\n  ADD COLUMN IF NOT EXISTS tipo_perda VARCHAR(50);\n\nCOMMENT ON COLUMN public.producao_perdas.ingrediente_id IS 'ID do ingrediente (insumo) em caso de sobra de insumo.';\nCOMMENT ON COLUMN public.producao_perdas.item_ordem_id IS 'ID do item da ordem (receita/produto) em caso de sobra de produto.';\nCOMMENT ON COLUMN public.producao_perdas.tipo_perda IS 'Tipo do registro: SOBRA, RESTO ou DESPERDICIO.';\n\n-- Relax the constraint on motivo_perda if it exists to allow custom values\n-- (In Supabase it's safer to just let the existing constraint be and use the new tipo_perda for our logic)\n"}	fix_producao_perdas_columns	zezolas27@gmail.com	\N	\N
20260320171036	{"-- Enable RLS and add basic policy for producao_perdas\nALTER TABLE public.producao_perdas ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS \\"Acesso por Unidade\\" ON public.producao_perdas;\nCREATE POLICY \\"Acesso por Unidade\\" ON public.producao_perdas\n    FOR ALL TO authenticated\n    USING (\n        unidade_id IN (\n            SELECT m.unidade_id \n            FROM public.app_user_memberships m \n            WHERE m.usuario_id = auth.uid()\n        )\n    )\n    WITH CHECK (\n        unidade_id IN (\n            SELECT m.unidade_id \n            FROM public.app_user_memberships m \n            WHERE m.usuario_id = auth.uid()\n        )\n    );\n\n-- Fallback policy for initial setup phase (Allows all authenticated if membership setup is complex)\n-- DROP POLICY IF EXISTS \\"Acesso Simples Autenticado\\" ON public.producao_perdas;\n-- CREATE POLICY \\"Acesso Simples Autenticado\\" ON public.producao_perdas FOR ALL TO authenticated USING (true) WITH CHECK (true);\n"}	enable_rls_for_producao_perdas	zezolas27@gmail.com	\N	\N
