20260321174113	{"-- Fase 6: Inteligência de Custos (Precificação)\n-- Adiciona cache de preços nos ingredientes e trigger para atualização em tempo real\n\n-- 1. Criação das colunas de cache em ingredientes\nALTER TABLE public.ingredientes \nADD COLUMN IF NOT EXISTS preco_ultima_compra NUMERIC DEFAULT 0,\nADD COLUMN IF NOT EXISTS custo_medio NUMERIC DEFAULT 0;\n\n-- 2. Função Trigger de Atualização do Custo do Ingrediente\nCREATE OR REPLACE FUNCTION trigger_atualiza_custo_ingrediente()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_total_value NUMERIC := 0;\n    v_total_quantity NUMERIC := 0;\n    v_weighted_average NUMERIC := 0;\n    v_latest_price NUMERIC := 0;\nBEGIN\n    -- Só age se o lote estiver atrelado a um ingrediente\n    IF NEW.ingrediente_id IS NOT NULL THEN\n        \n        -- A. Cálculo do Custo Médio Ponderado\n        -- Soma financeira do estoque dividido pela quantidade física\n        SELECT \n            COALESCE(SUM(quantidade_atual * valor_unitario), 0),\n            COALESCE(SUM(quantidade_atual), 0)\n        INTO \n            v_total_value, \n            v_total_quantity\n        FROM public.estoque_lotes\n        WHERE ingrediente_id = NEW.ingrediente_id \n          AND quantidade_atual > 0\n          AND (status_lote = 'ATIVO' OR status_lote = 'APROVADO'); -- Considera apenas lotes aptos\n\n        IF v_total_quantity > 0 THEN\n            v_weighted_average := v_total_value / v_total_quantity;\n        ELSE\n            -- Se zerou o estoque, mantém o último preço como referência de custo médio para não quebrar CMV teórico\n            v_weighted_average := NEW.valor_unitario;\n        END IF;\n\n        -- B. Busca do Último Preço de Compra (Last Price)\n        -- Pega a compra cronologicamente mais recente\n        SELECT valor_unitario INTO v_latest_price\n        FROM public.estoque_lotes\n        WHERE ingrediente_id = NEW.ingrediente_id\n          AND valor_unitario > 0\n        ORDER BY data_recebimento DESC NULLS LAST, created_at DESC\n        LIMIT 1;\n\n        -- Fallback caso não encontre\n        v_latest_price := COALESCE(v_latest_price, NEW.valor_unitario, 0);\n\n        -- C. Atualiza o cache na tabela principal de ingredientes\n        UPDATE public.ingredientes\n        SET \n            preco_ultima_compra = v_latest_price,\n            custo_medio = v_weighted_average\n        WHERE id = NEW.ingrediente_id;\n        \n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 3. Acoplando o Trigger na tabela de Lotes (Compras)\nDROP TRIGGER IF EXISTS atualiza_custo_ingrediente_trigger ON public.estoque_lotes;\nCREATE TRIGGER atualiza_custo_ingrediente_trigger\nAFTER INSERT OR UPDATE OF quantidade_atual, valor_unitario, status_lote\nON public.estoque_lotes\nFOR EACH ROW EXECUTE FUNCTION trigger_atualiza_custo_ingrediente();\n"}	custo_ingredientes_cache	zezolas27@gmail.com	\N	\N
20260321180135	{"-- 1. Add missing column to estoque_lotes if not exists\nDO $$ \nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'estoque_lotes' AND column_name = 'valor_total') THEN\n        ALTER TABLE public.estoque_lotes ADD COLUMN valor_total NUMERIC DEFAULT 0;\n    END IF;\nEND $$;\n\n-- 2. Update trigger_estoque_compra_to_ledger to use valor_total\nCREATE OR REPLACE FUNCTION trigger_estoque_compra_to_ledger()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_conta_passivo_id UUID;\n    v_conta_custo_insumo_id UUID;\n    v_transacao_id UUID;\n    v_valor_total NUMERIC;\nBEGIN\n    -- Se tem fornecedor e preço, foi uma COMPRA de insumo.\n    IF NEW.fornecedor_id IS NOT NULL AND (NEW.valor_total > 0 OR NEW.valor_unitario > 0) THEN\n        \n        -- Usa o valor_total se estiver disponível. Caso contrário, assume que valor_unitario é o preço do lote inteiro se qty for 1, ou calcula.\n        -- Como garantimos que o compras app passe valor_total, isso resolverá a ambiguidade.\n        v_valor_total := COALESCE(NEW.valor_total, (NEW.valor_unitario * NEW.quantidade_atual));\n        \n        -- Busca conta de \\"Contas a Pagar / Passivo\\" e conta de \\"Custo Insumos\\"\n        SELECT id INTO v_conta_passivo_id FROM public.fin_contas WHERE tipo = 'PASSIVO' AND ativo = true LIMIT 1;\n        SELECT id INTO v_conta_custo_insumo_id FROM public.fin_contas WHERE tipo = 'DESPESA' AND ativo = true LIMIT 1;\n\n        IF v_conta_passivo_id IS NOT NULL AND v_valor_total > 0 THEN\n            INSERT INTO public.fin_transacoes (unidade_id, descricao, data_competencia, origem_modulo, origem_id, valor_total)\n            VALUES (NEW.unidade_id, 'Entrada de Mercadoria NF: ' || COALESCE(NEW.nota_fiscal, 'S/N'), CURRENT_DATE, 'ESTOQUE', NEW.id, v_valor_total)\n            RETURNING id INTO v_transacao_id;\n\n            -- Aumento de Passivo (Dívida) = Crédito\n            INSERT INTO public.fin_lancamentos (transacao_id, conta_id, tipo_lancamento, valor)\n            VALUES (v_transacao_id, v_conta_passivo_id, 'CREDITO', v_valor_total);\n            \n            -- Aumento de Custo/Ativo = Débito\n            IF v_conta_custo_insumo_id IS NOT NULL THEN\n                INSERT INTO public.fin_lancamentos (transacao_id, conta_id, tipo_lancamento, valor)\n                VALUES (v_transacao_id, v_conta_custo_insumo_id, 'DEBITO', v_valor_total);\n            END IF;\n        END IF;\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 3. Update trigger_atualiza_custo_ingrediente to calculate accurate unit cost normalized by peso_unitario_g\nCREATE OR REPLACE FUNCTION trigger_atualiza_custo_ingrediente()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_total_value NUMERIC := 0;\n    v_total_quantity NUMERIC := 0;\n    v_weighted_average NUMERIC := 0;\n    v_latest_price NUMERIC := 0;\n    v_peso_unitario NUMERIC := 1000;\nBEGIN\n    IF NEW.ingrediente_id IS NOT NULL THEN\n        \n        -- Pega a unidade base de cálculo do ingrediente\n        SELECT COALESCE(peso_unitario_g, 1000) INTO v_peso_unitario FROM public.ingredientes WHERE id = NEW.ingrediente_id;\n\n        -- A. Custo Médio Ponderado = Soma Financeira Total / Quantidade Física Total\n        SELECT \n            COALESCE(SUM(COALESCE(valor_total, quantidade_atual * valor_unitario)), 0),\n            COALESCE(SUM(quantidade_atual), 0)\n        INTO \n            v_total_value, \n            v_total_quantity\n        FROM public.estoque_lotes\n        WHERE ingrediente_id = NEW.ingrediente_id \n          AND quantidade_atual > 0\n          AND (status_lote = 'ATIVO' OR status_lote = 'APROVADO' OR status_lote = 'RECEBIDO' OR status_lote = 'PREVISTO');\n\n        IF v_total_quantity > 0 THEN\n            -- Custo por grama * peso unitario = Custo de Reposição (e.g. preço por Kg)\n            v_weighted_average := (v_total_value / v_total_quantity) * v_peso_unitario;\n        ELSE\n            v_weighted_average := (COALESCE(NEW.valor_total, (NEW.valor_unitario * NEW.quantidade_atual)) / NULLIF(NEW.quantidade_atual, 0)) * v_peso_unitario;\n        END IF;\n\n        -- B. Busca do Último Preço (Last Price)\n        SELECT (COALESCE(valor_total, quantidade_atual * valor_unitario) / NULLIF(quantidade_atual, 0)) * v_peso_unitario \n        INTO v_latest_price\n        FROM public.estoque_lotes\n        WHERE ingrediente_id = NEW.ingrediente_id AND (valor_total > 0 OR valor_unitario > 0)\n        ORDER BY data_recebimento DESC NULLS LAST, created_at DESC\n        LIMIT 1;\n\n        v_latest_price := COALESCE(v_latest_price, (COALESCE(NEW.valor_total, (NEW.valor_unitario * NEW.quantidade_atual)) / NULLIF(NEW.quantidade_atual, 0)) * v_peso_unitario, 0);\n\n        -- C. Atualiza o cache na tabela de ingredientes\n        UPDATE public.ingredientes\n        SET \n            preco_ultima_compra = v_latest_price,\n            custo_medio = v_weighted_average\n        WHERE id = NEW.ingrediente_id;\n        \n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;"}	correcao_lotes_estoque_valor_total	zezolas27@gmail.com	\N	\N
20260321180643	{"-- 1. Adicionar colunas financeiras necessárias na tabela principal e ativa\nALTER TABLE public.lotes_estoque ADD COLUMN IF NOT EXISTS valor_unitario NUMERIC DEFAULT 0;\nALTER TABLE public.lotes_estoque ADD COLUMN IF NOT EXISTS valor_total NUMERIC DEFAULT 0;\nALTER TABLE public.lotes_estoque ADD COLUMN IF NOT EXISTS cliente_id UUID REFERENCES public.clientes(id);\n\n-- 2. Migrar o Gatilho de Contas a Pagar / DRE (Contabilidade)\nCREATE OR REPLACE FUNCTION trigger_lote_compra_to_ledger()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_conta_passivo_id UUID;\n    v_conta_custo_insumo_id UUID;\n    v_transacao_id UUID;\n    v_valor_total NUMERIC;\nBEGIN\n    IF NEW.fornecedor_id IS NOT NULL AND (NEW.valor_total > 0 OR NEW.valor_unitario > 0) THEN\n        v_valor_total := COALESCE(NEW.valor_total, (NEW.valor_unitario * NEW.quantidade_atual_g_ml));\n        \n        SELECT id INTO v_conta_passivo_id FROM public.fin_contas WHERE tipo = 'PASSIVO' AND ativo = true LIMIT 1;\n        SELECT id INTO v_conta_custo_insumo_id FROM public.fin_contas WHERE tipo = 'DESPESA' AND ativo = true LIMIT 1;\n\n        IF v_conta_passivo_id IS NOT NULL AND v_valor_total > 0 THEN\n            INSERT INTO public.fin_transacoes (unidade_id, descricao, data_competencia, origem_modulo, origem_id, valor_total)\n            VALUES (NEW.unidade_id, 'Entrada de Mercadoria NF: ' || COALESCE(NEW.nota_fiscal, 'S/N'), CURRENT_DATE, 'ESTOQUE', NEW.id, v_valor_total)\n            RETURNING id INTO v_transacao_id;\n\n            INSERT INTO public.fin_lancamentos (transacao_id, conta_id, tipo_lancamento, valor)\n            VALUES (v_transacao_id, v_conta_passivo_id, 'CREDITO', v_valor_total);\n            \n            IF v_conta_custo_insumo_id IS NOT NULL THEN\n                INSERT INTO public.fin_lancamentos (transacao_id, conta_id, tipo_lancamento, valor)\n                VALUES (v_transacao_id, v_conta_custo_insumo_id, 'DEBITO', v_valor_total);\n            END IF;\n        END IF;\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS lote_compra_to_ledger_trigger ON public.lotes_estoque;\nCREATE TRIGGER lote_compra_to_ledger_trigger\nAFTER INSERT ON public.lotes_estoque\nFOR EACH ROW EXECUTE FUNCTION trigger_lote_compra_to_ledger();\n\n-- 3. Migrar Gatilho de Inflação e Ficha Técnica (Precificação)\nCREATE OR REPLACE FUNCTION trigger_atualiza_custo_ingrediente_lotes()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_total_value NUMERIC := 0;\n    v_total_quantity NUMERIC := 0;\n    v_weighted_average NUMERIC := 0;\n    v_latest_price NUMERIC := 0;\n    v_peso_unitario NUMERIC := 1000;\nBEGIN\n    IF NEW.ingrediente_id IS NOT NULL THEN\n        SELECT COALESCE(peso_unitario_g, 1000) INTO v_peso_unitario FROM public.ingredientes WHERE id = NEW.ingrediente_id;\n\n        SELECT \n            COALESCE(SUM(COALESCE(valor_total, quantidade_atual_g_ml * valor_unitario)), 0),\n            COALESCE(SUM(quantidade_atual_g_ml), 0)\n        INTO \n            v_total_value, \n            v_total_quantity\n        FROM public.lotes_estoque\n        WHERE ingrediente_id = NEW.ingrediente_id \n          AND quantidade_atual_g_ml > 0\n          AND (status = 'ATIVO' OR status = 'APROVADO' OR status = 'RECEBIDO' OR status = 'PREVISTO');\n\n        IF v_total_quantity > 0 THEN\n            v_weighted_average := (v_total_value / v_total_quantity) * v_peso_unitario;\n        ELSE\n            v_weighted_average := (COALESCE(NEW.valor_total, (NEW.valor_unitario * NEW.quantidade_atual_g_ml)) / NULLIF(NEW.quantidade_atual_g_ml, 0)) * v_peso_unitario;\n        END IF;\n\n        SELECT (COALESCE(valor_total, quantidade_atual_g_ml * valor_unitario) / NULLIF(quantidade_atual_g_ml, 0)) * v_peso_unitario \n        INTO v_latest_price\n        FROM public.lotes_estoque\n        WHERE ingrediente_id = NEW.ingrediente_id AND (valor_total > 0 OR valor_unitario > 0)\n        ORDER BY created_at DESC\n        LIMIT 1;\n\n        v_latest_price := COALESCE(v_latest_price, (COALESCE(NEW.valor_total, (NEW.valor_unitario * NEW.quantidade_atual_g_ml)) / NULLIF(NEW.quantidade_atual_g_ml, 0)) * v_peso_unitario, 0);\n\n        UPDATE public.ingredientes\n        SET \n            preco_ultima_compra = v_latest_price,\n            custo_medio = v_weighted_average\n        WHERE id = NEW.ingrediente_id;\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS atualiza_custo_ingrediente_lotes_trigger ON public.lotes_estoque;\nCREATE TRIGGER atualiza_custo_ingrediente_lotes_trigger\nAFTER INSERT OR UPDATE OF valor_unitario, valor_total, quantidade_atual_g_ml, status ON public.lotes_estoque\nFOR EACH ROW EXECUTE FUNCTION trigger_atualiza_custo_ingrediente_lotes();\n\n\n-- 4. Excluir a tabela velha em segurança (cascade apagará referências nas chaves estrangeiras)\nDROP TABLE IF EXISTS public.estoque_lotes CASCADE;\n\n-- 5. Restaurar as Constraints das tabelas que foram esvaziadas pelo CASCADE conectando na oficial\nDO $$\nBEGIN\n    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'producao_consumos' AND column_name = 'estoque_lote_id') THEN\n        ALTER TABLE public.producao_consumos \n        ADD CONSTRAINT producao_consumos_lotes_estoque_fk \n        FOREIGN KEY (estoque_lote_id) REFERENCES public.lotes_estoque(id);\n    END IF;\n\n    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'producao_perdas' AND column_name = 'estoque_lote_id') THEN\n        ALTER TABLE public.producao_perdas \n        ADD CONSTRAINT producao_perdas_lotes_estoque_fk \n        FOREIGN KEY (estoque_lote_id) REFERENCES public.lotes_estoque(id);\n    END IF;\n\n    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'estoque_movimentacoes' AND column_name = 'lote_id') THEN\n        ALTER TABLE public.estoque_movimentacoes \n        ADD CONSTRAINT estoque_movimentacoes_lotes_estoque_fk \n        FOREIGN KEY (lote_id) REFERENCES public.lotes_estoque(id);\n    END IF;\nEND $$;\n"}	correcao_dualidade_lotes_estoque	zezolas27@gmail.com	\N	\N
20260321185801	{"ALTER TABLE lotes_estoque ALTER COLUMN data_validade_rotulo DROP NOT NULL;\nALTER TABLE lotes_estoque ALTER COLUMN data_fabricacao DROP NOT NULL;\nCOMMENT ON COLUMN lotes_estoque.data_validade_rotulo IS 'Data de validade do fabricante. Pode ser nula no status PREVISTO.';\nCOMMENT ON COLUMN lotes_estoque.data_fabricacao IS 'Data de fabricação. Pode ser nula no status PREVISTO.';"}	make_lotes_estoque_dates_nullable	zezolas27@gmail.com	\N	\N
20260321191232	{"-- Definir 1000 como padrão para peso_unitario_g e atualizar nulos\nALTER TABLE public.ingredientes ALTER COLUMN peso_unitario_g SET DEFAULT 1000;\nUPDATE public.ingredientes SET peso_unitario_g = 1000 WHERE peso_unitario_g IS NULL;\n\n-- Também garantir que o trigger use 1000 como fallback (já faz, mas reforça consistência)\n-- Não é estritamente necessário mudar o trigger se ele já usa COALESCE(..., 1000)\n"}	fix_ingredientes_peso_unitario_default	zezolas27@gmail.com	\N	\N
20260321200444	{"CREATE TABLE materiais (\n  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,\n  cliente_id UUID REFERENCES clientes(id) NOT NULL,\n  nome TEXT NOT NULL,\n  tipo_material TEXT CHECK (tipo_material IN ('EMBALAGEM', 'UTENSILIO', 'MANUTENCAO', 'LIMPEZA', 'OUTROS')) NOT NULL,\n  unidade_medida TEXT NOT NULL,\n  custo_medio NUMERIC DEFAULT 0,\n  preco_ultima_compra NUMERIC DEFAULT 0,\n  ativo BOOLEAN DEFAULT true,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Habilitar RLS\nALTER TABLE materiais ENABLE ROW LEVEL SECURITY;\n\n-- Politicas RLS (Clientes acessam apenas os próprios materiais)\nCREATE POLICY \\"Clientes podem ver seus materiais\\"\nON materiais FOR SELECT\nUSING (cliente_id IN (\n    SELECT id FROM clientes WHERE id = auth.uid() OR created_by = auth.uid()\n));\n\nCREATE POLICY \\"Clientes podem inserir materiais\\"\nON materiais FOR INSERT\nWITH CHECK (cliente_id IN (\n    SELECT id FROM clientes WHERE id = auth.uid() OR created_by = auth.uid()\n));\n\nCREATE POLICY \\"Clientes podem atualizar materiais\\"\nON materiais FOR UPDATE\nUSING (cliente_id IN (\n    SELECT id FROM clientes WHERE id = auth.uid() OR created_by = auth.uid()\n));\n\nCREATE POLICY \\"Clientes podem deletar materiais\\"\nON materiais FOR DELETE\nUSING (cliente_id IN (\n    SELECT id FROM clientes WHERE id = auth.uid() OR created_by = auth.uid()\n));\n\n-- Adicionar trigger para updated_at se a função existir ou criar manual\nCREATE OR REPLACE FUNCTION set_materiais_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = NOW();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER update_materiais_updated_at\nBEFORE UPDATE ON materiais\nFOR EACH ROW\nEXECUTE FUNCTION set_materiais_updated_at();\n"}	create_materiais_schema	zezolas27@gmail.com	\N	\N
20260322004310	{"-- Exclui a política antiga baseada em perfis que estava falhando\nDROP POLICY IF EXISTS \\"Acesso as Contas Financeiras\\" ON public.fin_contas;\n\n-- Cria a nova política robusta baseada nas permissões de unidade do usuário\nCREATE POLICY \\"Acesso as Contas Financeiras\\" ON public.fin_contas\nFOR ALL USING (cliente_id IN (\n    SELECT cu.cliente_id \n    FROM public.permissoes_usuario_unidade puu\n    JOIN public.cliente_unidades cu ON cu.id = puu.unidade_id\n    WHERE puu.usuario_id = auth.uid()\n));\n\n-- Adiciona a cláusula WITH CHECK explicitamente para garantir que INSERTs também funcionem\nALTER POLICY \\"Acesso as Contas Financeiras\\" ON public.fin_contas\nWITH CHECK (cliente_id IN (\n    SELECT cu.cliente_id \n    FROM public.permissoes_usuario_unidade puu\n    JOIN public.cliente_unidades cu ON cu.id = puu.unidade_id\n    WHERE puu.usuario_id = auth.uid()\n));\n"}	fix_fin_contas_rlp	zezolas27@gmail.com	\N	\N
20260323005222	{"-- Migration: Create fin_vendas_mensais table\n-- Description: Stores monthly sales data for recipes to support Menu Engineering (BCG/Kasavana)\n\nCREATE TABLE IF NOT EXISTS public.fin_vendas_mensais (\n    id UUID PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    receita_id UUID NOT NULL REFERENCES public.receitas(id) ON DELETE CASCADE,\n    mes_ano DATE NOT NULL, -- Always first day of the month\n    quantidade_vendida NUMERIC NOT NULL DEFAULT 0,\n    preco_venda NUMERIC NOT NULL DEFAULT 0,\n    created_at TIMESTAMPTZ DEFAULT now(),\n    updated_at TIMESTAMPTZ DEFAULT now(),\n    UNIQUE(cliente_id, receita_id, mes_ano)\n);\n\n-- Enable RLS\nALTER TABLE public.fin_vendas_mensais ENABLE ROW LEVEL SECURITY;\n\n-- Policies (Simplified for now, matching other tables)\n-- First drop if exists to avoid errors on reapplying\nDROP POLICY IF EXISTS \\"Enable all for authenticated users\\" ON public.fin_vendas_mensais;\nCREATE POLICY \\"Enable all for authenticated users\\" \nON public.fin_vendas_mensais \nFOR ALL \nUSING (auth.role() = 'authenticated');\n\n-- Trigger to update updated_at\nCREATE OR REPLACE FUNCTION update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$$ language 'plpgsql';\n\nDROP TRIGGER IF EXISTS tr_update_fin_vendas_mensais_updated_at ON public.fin_vendas_mensais;\nCREATE TRIGGER tr_update_fin_vendas_mensais_updated_at\nBEFORE UPDATE ON public.fin_vendas_mensais\nFOR EACH ROW\nEXECUTE FUNCTION update_updated_at_column();"}	create_vendas_mensais	zezolas27@gmail.com	\N	\N
