20260323200716	{"ALTER TABLE cliente_categorias_produto ADD COLUMN IF NOT EXISTS modalidade text;\n\n-- Update existing categories to have a default modality if they are standard ones\nUPDATE cliente_categorias_produto SET modalidade = 'ALIMENTOS' WHERE nome IN ('Alimentos', 'Frutas', 'Verduras', 'Carnes') AND modalidade IS NULL;\nUPDATE cliente_categorias_produto SET modalidade = 'LIMPEZA' WHERE nome = 'Limpeza' AND modalidade IS NULL;\nUPDATE cliente_categorias_produto SET modalidade = 'EMBALAGENS' WHERE nome = 'Embalagens' AND modalidade IS NULL;\nUPDATE cliente_categorias_produto SET modalidade = 'MANUTENCAO' WHERE nome = 'Manutenção' AND modalidade IS NULL;\nUPDATE cliente_categorias_produto SET modalidade = 'UTENSILIOS' WHERE nome = 'Utensílios' AND modalidade IS NULL;\nUPDATE cliente_categorias_produto SET modalidade = 'EPI_EPC' WHERE (nome = 'EPIs/EPCs' OR nome = 'EPI/EPC') AND modalidade IS NULL;\nUPDATE cliente_categorias_produto SET modalidade = 'UNIFORMES' WHERE nome = 'Uniformes' AND modalidade IS NULL;\nUPDATE cliente_categorias_produto SET modalidade = 'PRIMEIROS_SOCORROS' WHERE nome = 'Primeiros Socorros' AND modalidade IS NULL;\n"}	add_modalidade_to_categorias	zezolas27@gmail.com	\N	\N
