20260324151837	{"ALTER TABLE public.fin_transacoes \nADD COLUMN IF NOT EXISTS data_vencimento DATE,\nADD COLUMN IF NOT EXISTS comprovante_url TEXT,\nADD COLUMN IF NOT EXISTS nota_fiscal TEXT;\n\nCOMMENT ON COLUMN public.fin_transacoes.data_vencimento IS 'Data de vencimento da transação (A pagar)';\nCOMMENT ON COLUMN public.fin_transacoes.comprovante_url IS 'Link para o arquivo de comprovante de pagamento';\nCOMMENT ON COLUMN public.fin_transacoes.nota_fiscal IS 'Número da nota fiscal associada';\n"}	add_accounts_payable_fields_to_fin_transacoes_v2	zezolas27@gmail.com	\N	\N
20260324154943	{"ALTER TABLE public.lotes_estoque ADD COLUMN IF NOT EXISTS data_vencimento_financeiro DATE;\n\n-- Populate existing lotes from fin_transacoes where possible (by nota_fiscal and unidade_id)\nUPDATE public.lotes_estoque l\nSET data_vencimento_financeiro = t.data_vencimento\nFROM public.fin_transacoes t\nWHERE l.nota_fiscal = t.nota_fiscal \n  AND l.unidade_id = t.unidade_id\n  AND l.data_vencimento_financeiro IS NULL;"}	add_vencimento_to_lotes	zezolas27@gmail.com	\N	\N
20260324203733	{"-- 1. Função Trigger de Atualização do Custo de Materiais (Embalagens, Limpeza, etc)\nCREATE OR REPLACE FUNCTION trigger_atualiza_custo_material_lotes()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_total_value NUMERIC := 0;\n    v_total_quantity NUMERIC := 0;\n    v_weighted_average NUMERIC := 0;\n    v_latest_price NUMERIC := 0;\nBEGIN\n    -- Só age se o lote estiver atrelado a um material\n    IF NEW.material_id IS NOT NULL THEN\n        \n        -- A. Cálculo do Custo Médio Ponderado\n        SELECT \n            COALESCE(SUM(valor_total), 0),\n            COALESCE(SUM(quantidade_atual_g_ml), 0)\n        INTO \n            v_total_value, \n            v_total_quantity\n        FROM public.lotes_estoque\n        WHERE material_id = NEW.material_id \n          AND quantidade_atual_g_ml > 0\n          AND (status = 'APROVADO' OR status = 'PREVISTO');\n\n        IF v_total_quantity > 0 THEN\n            -- Para materiais, o valor_total já é para a quantidade_atual_g_ml (que para materiais costuma ser 1 un = 1.000 se cadastrado como KG ou 1 se UN)\n            v_weighted_average := v_total_value / v_total_quantity;\n        ELSE\n            v_weighted_average := COALESCE(NEW.valor_unitario, 0);\n        END IF;\n\n        -- B. Busca do Último Preço de Compra\n        SELECT valor_unitario INTO v_latest_price\n        FROM public.lotes_estoque\n        WHERE material_id = NEW.material_id\n          AND valor_unitario > 0\n        ORDER BY created_at DESC\n        LIMIT 1;\n\n        v_latest_price := COALESCE(v_latest_price, NEW.valor_unitario, 0);\n\n        -- C. Atualiza o cache na tabela principal de materiais\n        UPDATE public.materiais\n        SET \n            preco_ultima_compra = v_latest_price,\n            custo_medio = v_weighted_average\n        WHERE id = NEW.material_id;\n        \n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 2. Acoplando o Trigger na tabela de Lotes\nDROP TRIGGER IF EXISTS atualiza_custo_material_lotes_trigger ON public.lotes_estoque;\nCREATE TRIGGER atualiza_custo_material_lotes_trigger\nAFTER INSERT OR UPDATE OF quantidade_atual_g_ml, valor_unitario, valor_total, status\nON public.lotes_estoque\nFOR EACH ROW EXECUTE FUNCTION trigger_atualiza_custo_material_lotes();\n\n-- Sincronizar dados existentes\nUPDATE public.lotes_estoque SET status = status WHERE material_id IS NOT NULL;"}	atualiza_custo_materiais_trigger	zezolas27@gmail.com	\N	\N
20260324204639	{"CREATE TABLE IF NOT EXISTS public.cliente_equipamentos_config (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    grupo TEXT NOT NULL,\n    nome TEXT NOT NULL,\n    ativo BOOLEAN DEFAULT TRUE,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Habilitar RLS\nALTER TABLE public.cliente_equipamentos_config ENABLE ROW LEVEL SECURITY;\n\n-- Políticas de acesso (Simplificadas para o contexto)\nCREATE POLICY \\"Acesso total p/ cliente\\" ON public.cliente_equipamentos_config\n    FOR ALL USING (cliente_id IS NOT NULL);\n\n-- Inserir dados iniciais solicitados (apenas se não existirem)\n-- Nota: Como o cliente_id varia, o código no frontend ou uma trigger poderia fazer isso por cliente.\n-- Mas vou deixar o frontend lidar com os defaults se estiver vazio.\n"}	create_equipamentos_config_table	zezolas27@gmail.com	\N	\N
20260324205022	{"ALTER TABLE public.cliente_equipamentos_config \nADD COLUMN IF NOT EXISTS parent_id UUID REFERENCES public.cliente_equipamentos_config(id) ON DELETE CASCADE;\n\n-- Atualizar os dados existentes para serem \\"pais\\" (nível categoria)\n-- No momento, 'grupo' é o nível 1 (Temperatura), 'nome' é o nível 2 (Refrigerados).\n-- Para manter a compatibilidade e a estrutura que o usuário quer:\n-- Nível 1: Grupo (sempre texto por enquanto)\n-- Nível 2: Categoria (o que já temos como 'nome')\n-- Nível 3: Sub-categoria (novos itens com parent_id apontando para a categoria)\n"}	add_parent_to_equip_config	zezolas27@gmail.com	\N	\N
