20260324220312	{"CREATE TABLE IF NOT EXISTS public.cliente_controle_temperatura (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cliente_id UUID REFERENCES public.clientes(id) ON DELETE CASCADE,\n    unidade_id UUID,\n    local_id UUID REFERENCES public.cliente_locais_estoque(id) ON DELETE CASCADE,\n    data DATE NOT NULL DEFAULT CURRENT_DATE,\n    periodo TEXT CHECK (periodo IN ('MANHA', 'TARDE')),\n    temp_equipamento NUMERIC,\n    temp_alimento NUMERIC,\n    status TEXT NOT NULL DEFAULT 'LIGADO' CHECK (status IN ('LIGADO', 'DESLIGADO', 'VAZIO')),\n    responsavel_id UUID DEFAULT auth.uid(),\n    obs TEXT,\n    created_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Index for performance\nCREATE INDEX idx_controle_temp_data ON public.cliente_controle_temperatura (data);\nCREATE INDEX idx_controle_temp_local ON public.cliente_controle_temperatura (local_id);\n"}	create_controle_temperatura_table	zezolas27@gmail.com	\N	\N
20260324221805	{"-- Adicionar equipamento_id e hora_afericao\nALTER TABLE public.cliente_controle_temperatura \nADD COLUMN equipamento_id UUID REFERENCES public.cliente_equipamentos_config(id) ON DELETE CASCADE,\nADD COLUMN hora_afericao TIME;\n\n-- Migrar dados existentes (se houver) de local_id para equipamento_id\n-- (Assumindo que local_id aponta para um local que tem equipamento_config_id)\nUPDATE public.cliente_controle_temperatura t\nSET equipamento_id = l.equipamento_config_id\nFROM public.cliente_locais_estoque l\nWHERE t.local_id = l.id AND t.equipamento_id IS NULL;\n\n-- Tornar equipamento_id obrigatório para novos registros\n-- (Pode haver restrições se existirem dados órfãos, mas aqui estamos em dev)\n-- ALTER TABLE public.cliente_controle_temperatura ALTER COLUMN equipamento_id SET NOT NULL;\n\n-- Atualizar restrição de unicidade: de local_id para equipamento_id\nALTER TABLE public.cliente_controle_temperatura DROP CONSTRAINT IF EXISTS unique_controle_temp_perday;\nALTER TABLE public.cliente_controle_temperatura ADD CONSTRAINT unique_controle_temp_equip_perday UNIQUE (equipamento_id, data, periodo);\n"}	update_controle_temperatura_all_equipments_and_time	zezolas27@gmail.com	\N	\N
