20260325002942	{"-- Drop existing constraint\nALTER TABLE public.materiais DROP CONSTRAINT IF EXISTS materiais_tipo_material_check;\n\n-- Create expanded constraint\nALTER TABLE public.materiais ADD CONSTRAINT materiais_tipo_material_check \nCHECK (tipo_material = ANY (ARRAY[\n    'EMBALAGEM'::text, \n    'UTENSILIO'::text, \n    'MANUTENCAO'::text, \n    'LIMPEZA'::text, \n    'OUTROS'::text, \n    'EPI_EPC'::text, \n    'UNIFORME'::text, \n    'PRIMEIROS_SOCORROS'::text\n]));\n\n-- Update existing items that might have been saved as OUTROS and could be better categorized if we knew their intent,\n-- but for now, we just ensure the constraint is active.\n"}	add_new_material_types_constraint	zezolas27@gmail.com	\N	\N
20260325205901	{"\n-- Migration: Create tables for PDV and Delivery platform integrations\n\n-- 1. PDV Integration Config\nCREATE TABLE IF NOT EXISTS public.fin_integracoes_pdv (\n    id UUID PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    unidade_id UUID REFERENCES public.cliente_unidades(id) ON DELETE SET NULL,\n    nome TEXT NOT NULL DEFAULT 'Meu PDV',\n    tipo_pdv TEXT NOT NULL DEFAULT 'OUTRO' CHECK (tipo_pdv IN ('TOTVS', 'STONE', 'CIELO', 'LINX', 'OUTRO')),\n    api_endpoint TEXT,\n    api_key_encrypted TEXT,\n    ativo BOOLEAN NOT NULL DEFAULT true,\n    created_at TIMESTAMPTZ DEFAULT now(),\n    updated_at TIMESTAMPTZ DEFAULT now()\n);\n\nALTER TABLE public.fin_integracoes_pdv ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Enable all for authenticated users\\" ON public.fin_integracoes_pdv FOR ALL USING (auth.role() = 'authenticated');\n\n-- 2. Delivery Platform Integration Config\nCREATE TABLE IF NOT EXISTS public.fin_integracoes_delivery (\n    id UUID PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    unidade_id UUID REFERENCES public.cliente_unidades(id) ON DELETE SET NULL,\n    plataforma TEXT NOT NULL DEFAULT 'OUTRO' CHECK (plataforma IN ('IFOOD', 'RAPPI', 'UBER_EATS', 'ANOTAAI', '99FOOD', 'OUTRO')),\n    nome_exibicao TEXT NOT NULL DEFAULT 'Minha Plataforma',\n    client_id TEXT,\n    client_secret_encrypted TEXT,\n    merchant_id TEXT,\n    webhook_url TEXT,\n    taxa_mdr NUMERIC NOT NULL DEFAULT 0,\n    ativo BOOLEAN NOT NULL DEFAULT true,\n    created_at TIMESTAMPTZ DEFAULT now(),\n    updated_at TIMESTAMPTZ DEFAULT now()\n);\n\nALTER TABLE public.fin_integracoes_delivery ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Enable all for authenticated users\\" ON public.fin_integracoes_delivery FOR ALL USING (auth.role() = 'authenticated');\n\n-- 3. Monthly Delivery Financial Data\nCREATE TABLE IF NOT EXISTS public.fin_vendas_delivery (\n    id UUID PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    unidade_id UUID REFERENCES public.cliente_unidades(id) ON DELETE SET NULL,\n    integracao_id UUID NOT NULL REFERENCES public.fin_integracoes_delivery(id) ON DELETE CASCADE,\n    mes_ano DATE NOT NULL,\n    receita_bruta NUMERIC NOT NULL DEFAULT 0,\n    taxa_plataforma NUMERIC NOT NULL DEFAULT 0,\n    repasse_liquido NUMERIC NOT NULL DEFAULT 0,\n    pedidos_total INTEGER NOT NULL DEFAULT 0,\n    ticket_medio NUMERIC NOT NULL DEFAULT 0,\n    origem TEXT NOT NULL DEFAULT 'MANUAL' CHECK (origem IN ('API', 'MANUAL')),\n    importado_em TIMESTAMPTZ DEFAULT now(),\n    created_at TIMESTAMPTZ DEFAULT now(),\n    updated_at TIMESTAMPTZ DEFAULT now(),\n    UNIQUE(integracao_id, mes_ano)\n);\n\nALTER TABLE public.fin_vendas_delivery ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Enable all for authenticated users\\" ON public.fin_vendas_delivery FOR ALL USING (auth.role() = 'authenticated');\n\n-- Triggers for updated_at\nCREATE TRIGGER tr_update_fin_integracoes_pdv_updated_at\nBEFORE UPDATE ON public.fin_integracoes_pdv\nFOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n\nCREATE TRIGGER tr_update_fin_integracoes_delivery_updated_at\nBEFORE UPDATE ON public.fin_integracoes_delivery\nFOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n\nCREATE TRIGGER tr_update_fin_vendas_delivery_updated_at\nBEFORE UPDATE ON public.fin_vendas_delivery\nFOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n"}	create_integracoes_delivery_tables	zezolas27@gmail.com	\N	\N
20260326010735	{"-- 1. Corrigir Trigger de Ingredientes\nCREATE OR REPLACE FUNCTION public.trigger_atualiza_custo_ingrediente_lotes()\n RETURNS trigger\n LANGUAGE plpgsql\n AS $function$\n DECLARE\n     v_total_value NUMERIC := 0;\n     v_total_quantity NUMERIC := 0;\n     v_weighted_average NUMERIC := 0;\n     v_latest_price NUMERIC := 0;\n     v_peso_unitario NUMERIC := 1000;\n BEGIN\n     -- Usamos COALESCE no ID pois o NEW pode ter ingredientes nulos em casos raros ou materiais\n     IF NEW.ingrediente_id IS NOT NULL THEN\n         SELECT COALESCE(peso_unitario_g, 1000) INTO v_peso_unitario FROM public.ingredientes WHERE id = NEW.ingrediente_id;\n \n         -- A. Cálculo do Custo Médio Ponderado (Somente lotes VÁLIDOS e ATIVOS)\n         SELECT \n             COALESCE(SUM(COALESCE(valor_total, quantidade_atual_g_ml * valor_unitario)), 0),\n             COALESCE(SUM(quantidade_atual_g_ml), 0)\n         INTO \n             v_total_value, \n             v_total_quantity\n         FROM public.lotes_estoque\n         WHERE ingrediente_id = NEW.ingrediente_id \n           AND quantidade_atual_g_ml > 0\n           AND (status = 'APROVADO' OR status = 'PREVISTO')\n           AND deleted_at IS NULL; -- CORREÇÃO: Ignorar excluídos\n \n         IF v_total_quantity > 0 THEN\n             v_weighted_average := (v_total_value / v_total_quantity) * v_peso_unitario;\n         ELSE\n             -- Fallback: se não há lotes ativos, tenta o valor do registro atual se ele não estiver sendo deletado\n             IF NEW.deleted_at IS NULL AND NEW.quantidade_atual_g_ml > 0 THEN\n                 v_weighted_average := (COALESCE(NEW.valor_total, (NEW.valor_unitario * NEW.quantidade_atual_g_ml)) / NEW.quantidade_atual_g_ml) * v_peso_unitario;\n             ELSE\n                 v_weighted_average := 0;\n             END IF;\n         END IF;\n \n         -- B. Busca do último preço efetivo (desconsiderando lotes sem valor ou EXCLUÍDOS)\n         SELECT (COALESCE(valor_total, quantidade_atual_g_ml * valor_unitario) / NULLIF(quantidade_atual_g_ml, 0)) * v_peso_unitario \n         INTO v_latest_price\n         FROM public.lotes_estoque\n         WHERE ingrediente_id = NEW.ingrediente_id \n           AND (valor_total > 0 OR valor_unitario > 0)\n           AND deleted_at IS NULL -- CORREÇÃO: Ignorar excluídos\n         ORDER BY created_at DESC\n         LIMIT 1;\n \n         -- Fallback se não encontrar nada válido\n         v_latest_price := COALESCE(v_latest_price, 0);\n \n         UPDATE public.ingredientes\n         SET \n             preco_ultima_compra = v_latest_price,\n             custo_medio = v_weighted_average\n         WHERE id = NEW.ingrediente_id;\n     END IF;\n     RETURN NEW;\n END;\n $function$;\n\n-- 2. Corrigir Trigger de Materiais (Embalagens/Limpeza/etc)\nCREATE OR REPLACE FUNCTION public.trigger_atualiza_custo_material_lotes()\n RETURNS trigger\n LANGUAGE plpgsql\n AS $function$\n DECLARE\n     v_total_value NUMERIC := 0;\n     v_total_quantity NUMERIC := 0;\n     v_weighted_average NUMERIC := 0;\n     v_latest_price NUMERIC := 0;\n BEGIN\n     IF NEW.material_id IS NOT NULL THEN\n         \n         -- A. Cálculo do Custo Médio Ponderado (Ignorando EXCLUÍDOS)\n         SELECT \n             COALESCE(SUM(valor_total), 0),\n             COALESCE(SUM(quantidade_atual_g_ml), 0)\n         INTO \n             v_total_value, \n             v_total_quantity\n         FROM public.lotes_estoque\n         WHERE material_id = NEW.material_id \n           AND quantidade_atual_g_ml > 0\n           AND (status = 'APROVADO' OR status = 'PREVISTO')\n           AND deleted_at IS NULL; -- CORREÇÃO: Ignorar excluídos\n \n         IF v_total_quantity > 0 THEN\n             v_weighted_average := v_total_value / v_total_quantity;\n         ELSE\n             IF NEW.deleted_at IS NULL THEN\n                 v_weighted_average := COALESCE(NEW.valor_unitario, 0);\n             ELSE\n                 v_weighted_average := 0;\n             END IF;\n         END IF;\n \n         -- B. Busca do Último Preço de Compra (Ignorando EXCLUÍDOS)\n         SELECT valor_unitario INTO v_latest_price\n         FROM public.lotes_estoque\n         WHERE material_id = NEW.material_id\n           AND valor_unitario > 0\n           AND deleted_at IS NULL -- CORREÇÃO: Ignorar excluídos\n         ORDER BY created_at DESC\n         LIMIT 1;\n \n         -- Fallback\n         v_latest_price := COALESCE(v_latest_price, 0);\n \n         UPDATE public.materiais\n         SET \n             preco_ultima_compra = v_latest_price,\n             custo_medio = v_weighted_average\n         WHERE id = NEW.material_id;\n         \n     END IF;\n \n     RETURN NEW;\n END;\n $function$;\n"}	fix_stale_cost_triggers	zezolas27@gmail.com	\N	\N
20260326011102	{"CREATE OR REPLACE FUNCTION public.trigger_atualiza_custo_ingrediente_lotes()\n RETURNS trigger\n LANGUAGE plpgsql\n AS $function$\n BEGIN\n     IF NEW.ingrediente_id IS NOT NULL THEN\n         UPDATE public.ingredientes\n         SET \n             preco_ultima_compra = 123, -- VALOR FORÇADO PARA DEBUG\n             custo_medio = 123\n         WHERE id = NEW.ingrediente_id;\n     END IF;\n     RETURN NEW;\n END;\n $function$;\n"}	debug_trigger_forced_value	zezolas27@gmail.com	\N	\N
20260326011243	{"-- 1. Restaurar Funções (sem o debug de valor fixo 123)\nCREATE OR REPLACE FUNCTION public.trigger_atualiza_custo_ingrediente_lotes()\n RETURNS trigger\n LANGUAGE plpgsql\n AS $function$\n DECLARE\n     v_total_value NUMERIC := 0;\n     v_total_quantity NUMERIC := 0;\n     v_weighted_average NUMERIC := 0;\n     v_latest_price NUMERIC := 0;\n     v_peso_unitario NUMERIC := 1000;\n BEGIN\n     IF NEW.ingrediente_id IS NOT NULL THEN\n         SELECT COALESCE(peso_unitario_g, 1000) INTO v_peso_unitario FROM public.ingredientes WHERE id = NEW.ingrediente_id;\n \n         -- A. Cálculo do Custo Médio Ponderado (Somente lotes VÁLIDOS e ATIVOS)\n         SELECT \n             COALESCE(SUM(COALESCE(valor_total, quantidade_atual_g_ml * valor_unitario)), 0),\n             COALESCE(SUM(quantidade_atual_g_ml), 0)\n         INTO \n             v_total_value, \n             v_total_quantity\n         FROM public.lotes_estoque\n         WHERE ingrediente_id = NEW.ingrediente_id \n           AND quantidade_atual_g_ml > 0\n           AND (status = 'APROVADO' OR status = 'PREVISTO')\n           AND deleted_at IS NULL;\n \n         IF v_total_quantity > 0 THEN\n             v_weighted_average := (v_total_value / v_total_quantity) * v_peso_unitario;\n         ELSE\n             IF NEW.deleted_at IS NULL AND NEW.quantidade_atual_g_ml > 0 THEN\n                 v_weighted_average := (COALESCE(NEW.valor_total, (NEW.valor_unitario * NEW.quantidade_atual_g_ml)) / NEW.quantidade_atual_g_ml) * v_peso_unitario;\n             ELSE\n                 v_weighted_average := 0;\n             END IF;\n         END IF;\n \n         -- B. Busca do último preço efetivo (desconsiderando lotes sem valor ou EXCLUÍDOS)\n         SELECT (COALESCE(valor_total, quantidade_atual_g_ml * valor_unitario) / NULLIF(quantidade_atual_g_ml, 0)) * v_peso_unitario \n         INTO v_latest_price\n         FROM public.lotes_estoque\n         WHERE ingrediente_id = NEW.ingrediente_id \n           AND (valor_total > 0 OR valor_unitario > 0)\n           AND deleted_at IS NULL\n         ORDER BY created_at DESC\n         LIMIT 1;\n \n         v_latest_price := COALESCE(v_latest_price, 0);\n \n         UPDATE public.ingredientes\n         SET \n             preco_ultima_compra = v_latest_price,\n             custo_medio = v_weighted_average\n         WHERE id = NEW.ingrediente_id;\n     END IF;\n     RETURN NEW;\n END;\n $function$;\n\nCREATE OR REPLACE FUNCTION public.trigger_atualiza_custo_material_lotes()\n RETURNS trigger\n LANGUAGE plpgsql\n AS $function$\n DECLARE\n     v_total_value NUMERIC := 0;\n     v_total_quantity NUMERIC := 0;\n     v_weighted_average NUMERIC := 0;\n     v_latest_price NUMERIC := 0;\n BEGIN\n     IF NEW.material_id IS NOT NULL THEN\n         SELECT \n             COALESCE(SUM(valor_total), 0),\n             COALESCE(SUM(quantidade_atual_g_ml), 0)\n         INTO \n             v_total_value, \n             v_total_quantity\n         FROM public.lotes_estoque\n         WHERE material_id = NEW.material_id \n           AND quantidade_atual_g_ml > 0\n           AND (status = 'APROVADO' OR status = 'PREVISTO')\n           AND deleted_at IS NULL;\n \n         IF v_total_quantity > 0 THEN\n             v_weighted_average := v_total_value / v_total_quantity;\n         ELSE\n             IF NEW.deleted_at IS NULL THEN\n                 v_weighted_average := COALESCE(NEW.valor_unitario, 0);\n             ELSE\n                 v_weighted_average := 0;\n             END IF;\n         END IF;\n \n         SELECT valor_unitario INTO v_latest_price\n         FROM public.lotes_estoque\n         WHERE material_id = NEW.material_id\n           AND valor_unitario > 0\n           AND deleted_at IS NULL\n         ORDER BY created_at DESC\n         LIMIT 1;\n \n         v_latest_price := COALESCE(v_latest_price, 0);\n \n         UPDATE public.materiais\n         SET \n             preco_ultima_compra = v_latest_price,\n             custo_medio = v_weighted_average\n         WHERE id = NEW.material_id;\n     END IF;\n     RETURN NEW;\n END;\n $function$;\n\n-- 2. Atualizar definições de Trigger para incluir DELETED_AT no UPDATE OF\nDROP TRIGGER IF EXISTS atualiza_custo_ingrediente_lotes_trigger ON public.lotes_estoque;\nCREATE TRIGGER atualiza_custo_ingrediente_lotes_trigger\nAFTER INSERT OR UPDATE OF valor_unitario, valor_total, quantidade_atual_g_ml, status, deleted_at\nON public.lotes_estoque\nFOR EACH ROW\nEXECUTE FUNCTION trigger_atualiza_custo_ingrediente_lotes();\n\nDROP TRIGGER IF EXISTS atualiza_custo_material_lotes_trigger ON public.lotes_estoque;\nCREATE TRIGGER atualiza_custo_material_lotes_trigger\nAFTER INSERT OR UPDATE OF valor_unitario, valor_total, quantidade_atual_g_ml, status, deleted_at\nON public.lotes_estoque\nFOR EACH ROW\nEXECUTE FUNCTION trigger_atualiza_custo_material_lotes();\n"}	fix_trigger_definitions_on_deletion	zezolas27@gmail.com	\N	\N
20260326012541	{"-- Tabela de sessões de inventário\nCREATE TABLE public.estoque_inventarios (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id),\n    local_estoque_id UUID REFERENCES public.cliente_locais_estoque(id),\n    responsavel_id UUID REFERENCES auth.users(id),\n    responsavel_nome TEXT,\n    status TEXT NOT NULL DEFAULT 'ABERTO' CHECK (status IN ('ABERTO', 'FINALIZADO', 'CANCELADO')),\n    data_inicio TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    data_fim TIMESTAMPTZ,\n    total_esperado INT DEFAULT 0,\n    total_conferido INT DEFAULT 0,\n    total_divergencias INT DEFAULT 0,\n    observacoes TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Tabela de itens conferidos no inventário\nCREATE TABLE public.estoque_inventario_itens (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    inventario_id UUID NOT NULL REFERENCES public.estoque_inventarios(id) ON DELETE CASCADE,\n    lote_id UUID NOT NULL REFERENCES public.lotes_estoque(id),\n    qtd_esperada_g NUMERIC NOT NULL DEFAULT 0,\n    qtd_conferida_g NUMERIC DEFAULT 0,\n    conferido BOOLEAN DEFAULT FALSE,\n    metodo TEXT DEFAULT 'MANUAL' CHECK (metodo IN ('MANUAL', 'QR_CODE')),\n    divergencia_g NUMERIC DEFAULT 0,\n    ajuste_aplicado BOOLEAN DEFAULT FALSE,\n    conferido_em TIMESTAMPTZ,\n    conferido_por UUID REFERENCES auth.users(id),\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Índices\nCREATE INDEX idx_inventarios_unidade ON public.estoque_inventarios(unidade_id);\nCREATE INDEX idx_inventarios_status ON public.estoque_inventarios(status);\nCREATE INDEX idx_inventario_itens_inventario ON public.estoque_inventario_itens(inventario_id);\nCREATE INDEX idx_inventario_itens_lote ON public.estoque_inventario_itens(lote_id);\n"}	create_inventory_tables	zezolas27@gmail.com	\N	\N
