20260327174755	{"-- 1. Adicionar coluna tipo na tabela fornecedores\nALTER TABLE public.fornecedores \nADD COLUMN IF NOT EXISTS tipo text DEFAULT 'FORNECEDOR';\n\n-- 2. Criar a tabela de configuração de categorias\nCREATE TABLE IF NOT EXISTS public.categorias_config (\n    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,\n    cliente_id uuid NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    tipo text NOT NULL CHECK (tipo IN ('FORNECEDOR', 'SERVICO')),\n    nome text NOT NULL,\n    documentos_obrigatorios text[] DEFAULT '{}',\n    created_at timestamptz DEFAULT now(),\n    updated_at timestamptz DEFAULT now(),\n    UNIQUE(cliente_id, tipo, nome)\n);\n\n-- 3. Habilitar RLS\nALTER TABLE public.categorias_config ENABLE ROW LEVEL SECURITY;\n\n-- 4. Criar políticas de RLS para categorias_config\nDROP POLICY IF EXISTS \\"Usuários podem ver categorias do seu cliente\\" ON public.categorias_config;\nCREATE POLICY \\"Usuários podem ver categorias do seu cliente\\"\nON public.categorias_config FOR SELECT\nTO authenticated\nUSING (cliente_id IN (\n    SELECT cliente_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\n));\n\nDROP POLICY IF EXISTS \\"Usuários podem gerenciar categorias do seu cliente\\" ON public.categorias_config;\nCREATE POLICY \\"Usuários podem gerenciar categorias do seu cliente\\"\nON public.categorias_config FOR ALL\nTO authenticated\nUSING (cliente_id IN (\n    SELECT cliente_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\n))\nWITH CHECK (cliente_id IN (\n    SELECT cliente_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\n));\n\n-- 5. Atualizar registros existentes (Legacy)\nUPDATE public.fornecedores SET tipo = 'FORNECEDOR' WHERE tipo IS NULL;\n"}	add_supplier_categories_config_v2	zezolas27@gmail.com	\N	\N
