20260327180656	{"-- 1. Create a temporary column\nALTER TABLE public.categorias_config ADD COLUMN documentos_obrigatorios_new jsonb DEFAULT '[]'::jsonb;\n\n-- 2. Migrate data using a function-based approach or a subquery in UPDATE\nUPDATE public.categorias_config\nSET documentos_obrigatorios_new = (\n    SELECT jsonb_agg(jsonb_build_object('nome', elem, 'ged_pasta_id', null))\n    FROM unnest(documentos_obrigatorios) AS elem\n)\nWHERE documentos_obrigatorios IS NOT NULL AND array_length(documentos_obrigatorios, 1) > 0;\n\n-- 3. Replace old column\nALTER TABLE public.categorias_config DROP COLUMN documentos_obrigatorios;\nALTER TABLE public.categorias_config RENAME COLUMN documentos_obrigatorios_new TO documentos_obrigatorios;\n"}	convert_docs_to_jsonb_metadata_v2	zezolas27@gmail.com	\N	\N
