20260328174854	{"-- 1. Modificações em ingredientes\nALTER TABLE public.ingredientes\nADD COLUMN IF NOT EXISTS preco_ultima_compra NUMERIC(15,4) DEFAULT 0,\nADD COLUMN IF NOT EXISTS estoque_minimo_kg NUMERIC(10,3) DEFAULT 0,\nADD COLUMN IF NOT EXISTS tempo_minimo_compra_dias INTEGER DEFAULT 0;\n\n-- 2. Modificações em fornecedores\nALTER TABLE public.fornecedores\nADD COLUMN IF NOT EXISTS lead_time_dias INTEGER DEFAULT 0,\nADD COLUMN IF NOT EXISTS frequencia_entrega VARCHAR(255) NULL;\n\n-- 3. Tabela fichas_tecnicas_uan\nCREATE TABLE IF NOT EXISTS public.fichas_tecnicas_uan (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    nome VARCHAR(255) NOT NULL,\n    categoria_uan VARCHAR(50) NOT NULL,\n    rendimento_porcoes INTEGER NOT NULL DEFAULT 1,\n    peso_porcao_g NUMERIC(10,2) NOT NULL,\n    modo_preparo TEXT,\n    tempo_preparo_min INTEGER,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())\n);\n\n-- 4. Tabela composicao_fichas_uan\nCREATE TABLE IF NOT EXISTS public.composicao_fichas_uan (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    ficha_uan_id UUID NOT NULL REFERENCES public.fichas_tecnicas_uan(id) ON DELETE CASCADE,\n    ingrediente_id UUID NOT NULL REFERENCES public.ingredientes(id) ON DELETE RESTRICT,\n    peso_bruto_g NUMERIC(12,4) NOT NULL,\n    peso_liquido_g NUMERIC(12,4) NOT NULL,\n    fator_correcao NUMERIC(10,4) NOT NULL DEFAULT 1,\n    indice_coccao NUMERIC(10,4) NOT NULL DEFAULT 1\n);\n\n-- 5. Tabelas cardapios_uan e cardapio_dias_uan\nCREATE TABLE IF NOT EXISTS public.cardapios_uan (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    nome_ciclo VARCHAR(255) NOT NULL,\n    data_inicio DATE NOT NULL,\n    data_fim DATE NOT NULL,\n    status VARCHAR(50) DEFAULT 'Rascunho',\n    comensais_estimados_dia INTEGER DEFAULT 100,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())\n);\n\nCREATE TABLE IF NOT EXISTS public.cardapio_dias_uan (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cardapio_id UUID NOT NULL REFERENCES public.cardapios_uan(id) ON DELETE CASCADE,\n    data_consumo DATE NOT NULL,\n    tipo_refeicao VARCHAR(50) NOT NULL,\n    ficha_uan_id UUID NOT NULL REFERENCES public.fichas_tecnicas_uan(id) ON DELETE RESTRICT,\n    fator_multiplicador NUMERIC(10,4) DEFAULT 1\n);\n\n-- 6. Tabela listas_compras_uan\nCREATE TABLE IF NOT EXISTS public.listas_compras_uan (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cardapio_id UUID NOT NULL REFERENCES public.cardapios_uan(id) ON DELETE CASCADE,\n    data_geracao TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),\n    status VARCHAR(50) DEFAULT 'Pendente',\n    itens_json JSONB NOT NULL DEFAULT '[]'::jsonb\n);"}	criacao_modulo_uan	zezolas27@gmail.com	\N	\N
