20260401213145	{"-- ==========================================\n-- FASE PCP/MRP: Foundation Schema\n-- ==========================================\n\n-- PARTE 1: ALTERAÇÕES EM TABELAS EXISTENTES\n\n-- 1.1 composicao_receitas — Adicionar FC e IC explícitos\nALTER TABLE public.composicao_receitas\nADD COLUMN IF NOT EXISTS fator_correcao NUMERIC NOT NULL DEFAULT 1,\nADD COLUMN IF NOT EXISTS indice_coccao NUMERIC NOT NULL DEFAULT 1;\n\nUPDATE public.composicao_receitas\nSET fator_correcao = CASE\n    WHEN peso_liquido_g > 0 AND peso_bruto_g > 0\n    THEN ROUND(peso_bruto_g / peso_liquido_g, 4)\n    ELSE 1\nEND\nWHERE fator_correcao = 1 AND peso_bruto_g > 0 AND peso_liquido_g > 0;\n\nCOMMENT ON COLUMN public.composicao_receitas.fator_correcao IS 'Fator de Correção (FC = PB/PL). Quanto do alimento in natura se perde no pré-preparo.';\nCOMMENT ON COLUMN public.composicao_receitas.indice_coccao IS 'Índice de Cocção (IC). Variação de peso/volume após cocção.';\n\n-- 1.2 producao_ordens — Rastreabilidade de origem e vínculo ao PMP\nALTER TABLE public.producao_ordens\nADD COLUMN IF NOT EXISTS origem_tipo VARCHAR(30) DEFAULT 'ORDEM_SERVICO',\nADD COLUMN IF NOT EXISTS pmp_periodo_id UUID;\n\nCOMMENT ON COLUMN public.producao_ordens.origem_tipo IS 'Origem da OP: ORDEM_SERVICO, CARDAPIO_UAN, MRP_AUTO';\n\n-- 1.3 producao_requisicoes — Vínculo com MRP e prioridade\nALTER TABLE public.producao_requisicoes\nADD COLUMN IF NOT EXISTS mrp_necessidade_id UUID,\nADD COLUMN IF NOT EXISTS prioridade VARCHAR(20) DEFAULT 'NORMAL';\n\nCOMMENT ON COLUMN public.producao_requisicoes.prioridade IS 'Prioridade da requisição: URGENTE, ALTA, NORMAL, BAIXA';\n\n-- 1.4 fornecedores — Parâmetros logísticos adicionais\nALTER TABLE public.fornecedores\nADD COLUMN IF NOT EXISTS lote_minimo_pedido NUMERIC DEFAULT 0,\nADD COLUMN IF NOT EXISTS dia_semana_entrega INTEGER[],\nADD COLUMN IF NOT EXISTS prazo_pagamento_dias INTEGER DEFAULT 30;\n\nCOMMENT ON COLUMN public.fornecedores.lote_minimo_pedido IS 'Quantidade mínima de pedido em gramas (g) exigida pelo fornecedor.';\nCOMMENT ON COLUMN public.fornecedores.dia_semana_entrega IS 'Dias da semana em que o fornecedor faz entregas (1=Dom, 2=Seg, ..., 7=Sáb).';\nCOMMENT ON COLUMN public.fornecedores.prazo_pagamento_dias IS 'Prazo de pagamento em dias após recebimento da NF.';\n\n-- 1.5 ingredientes — Shelf life e temperatura\nALTER TABLE public.ingredientes\nADD COLUMN IF NOT EXISTS shelf_life_dias INTEGER,\nADD COLUMN IF NOT EXISTS temperatura_armazenamento VARCHAR(20);\n\nCOMMENT ON COLUMN public.ingredientes.shelf_life_dias IS 'Vida útil média do insumo em dias após recebimento.';\nCOMMENT ON COLUMN public.ingredientes.temperatura_armazenamento IS 'Condição de temperatura: AMBIENTE, REFRIGERADO ou CONGELADO.';"}	pcp_mrp_foundation	zezolas27@gmail.com	\N	\N
20260401213212	{"-- PARTE 2: NOVAS TABELAS — PMP\n\nCREATE TABLE IF NOT EXISTS public.pmp_periodos (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id) ON DELETE CASCADE,\n    nome TEXT NOT NULL,\n    tipo VARCHAR(20) DEFAULT 'SEMANAL' CHECK (tipo IN ('SEMANAL', 'MENSAL', 'CUSTOMIZADO')),\n    data_inicio DATE NOT NULL,\n    data_fim DATE NOT NULL,\n    status VARCHAR(30) DEFAULT 'RASCUNHO' CHECK (status IN ('RASCUNHO', 'APROVADO', 'EXECUTANDO', 'CONCLUIDO', 'CANCELADO')),\n    observacoes TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    created_by UUID REFERENCES auth.users(id),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    CONSTRAINT pmp_datas_validas CHECK (data_fim >= data_inicio)\n);\n\nCREATE INDEX IF NOT EXISTS idx_pmp_periodos_unidade ON pmp_periodos(unidade_id);\nCREATE INDEX IF NOT EXISTS idx_pmp_periodos_status ON pmp_periodos(status);\nCREATE INDEX IF NOT EXISTS idx_pmp_periodos_datas ON pmp_periodos(data_inicio, data_fim);\n\nCREATE TABLE IF NOT EXISTS public.pmp_demandas (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    pmp_periodo_id UUID NOT NULL REFERENCES public.pmp_periodos(id) ON DELETE CASCADE,\n    origem_tipo VARCHAR(30) NOT NULL CHECK (origem_tipo IN ('ORDEM_SERVICO', 'CARDAPIO_UAN')),\n    origem_id UUID,\n    receita_id UUID REFERENCES public.receitas(id),\n    ficha_uan_id UUID REFERENCES public.fichas_tecnicas_uan(id),\n    data_necessidade DATE NOT NULL,\n    quantidade_planejada NUMERIC(12,3) NOT NULL CHECK (quantidade_planejada > 0),\n    unidade_medida VARCHAR(10) DEFAULT 'UN' CHECK (unidade_medida IN ('UN', 'KG', 'PORCOES', 'LOTE')),\n    observacao TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    CONSTRAINT pmp_demanda_tipo_valido CHECK (\n        (origem_tipo = 'ORDEM_SERVICO' AND receita_id IS NOT NULL) OR\n        (origem_tipo = 'CARDAPIO_UAN' AND ficha_uan_id IS NOT NULL)\n    )\n);\n\nCREATE INDEX IF NOT EXISTS idx_pmp_demandas_periodo ON pmp_demandas(pmp_periodo_id);\nCREATE INDEX IF NOT EXISTS idx_pmp_demandas_data ON pmp_demandas(data_necessidade);\n\n-- PARTE 3: NOVAS TABELAS — MRP\n\nCREATE TABLE IF NOT EXISTS public.mrp_necessidades (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    pmp_periodo_id UUID NOT NULL REFERENCES public.pmp_periodos(id) ON DELETE CASCADE,\n    ingrediente_id UUID NOT NULL REFERENCES public.ingredientes(id),\n    data_necessidade DATE NOT NULL,\n    necessidade_bruta_g NUMERIC(14,3) NOT NULL DEFAULT 0,\n    estoque_disponivel_g NUMERIC(14,3) DEFAULT 0,\n    recebimentos_programados_g NUMERIC(14,3) DEFAULT 0,\n    necessidade_liquida_g NUMERIC(14,3) DEFAULT 0,\n    estoque_seguranca_aplicado_g NUMERIC(14,3) DEFAULT 0,\n    acao_sugerida VARCHAR(30) CHECK (acao_sugerida IN ('COMPRAR', 'PRODUZIR', 'SUFICIENTE', 'TRANSFERIR')),\n    data_sugerida_pedido DATE,\n    quantidade_sugerida_compra_g NUMERIC(14,3),\n    fornecedor_sugerido_id UUID REFERENCES public.fornecedores(id),\n    detalhamento JSONB,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    UNIQUE(pmp_periodo_id, ingrediente_id, data_necessidade)\n);\n\nCREATE INDEX IF NOT EXISTS idx_mrp_necessidades_periodo ON mrp_necessidades(pmp_periodo_id);\nCREATE INDEX IF NOT EXISTS idx_mrp_necessidades_ingrediente ON mrp_necessidades(ingrediente_id);\nCREATE INDEX IF NOT EXISTS idx_mrp_necessidades_acao ON mrp_necessidades(acao_sugerida);\n\nCREATE TABLE IF NOT EXISTS public.mrp_ordens_planejadas (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    mrp_necessidade_id UUID REFERENCES public.mrp_necessidades(id) ON DELETE CASCADE,\n    ingrediente_id UUID NOT NULL REFERENCES public.ingredientes(id),\n    tipo_ordem VARCHAR(30) NOT NULL CHECK (tipo_ordem IN ('COMPRA', 'PRODUCAO_INTERNA')),\n    quantidade_sugerida_g NUMERIC(14,3) NOT NULL,\n    data_sugerida_pedido DATE,\n    data_necessidade DATE,\n    lead_time_considerado INTEGER,\n    fornecedor_sugerido_id UUID REFERENCES public.fornecedores(id),\n    status VARCHAR(30) DEFAULT 'SUGERIDA' CHECK (status IN ('SUGERIDA', 'APROVADA', 'CONVERTIDA', 'CANCELADA')),\n    convertida_cotacao_id UUID,\n    motivo_cancelamento TEXT,\n    aprovado_por UUID REFERENCES auth.users(id),\n    aprovado_em TIMESTAMPTZ,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_mrp_ordens_status ON mrp_ordens_planejadas(status);\nCREATE INDEX IF NOT EXISTS idx_mrp_ordens_ingrediente ON mrp_ordens_planejadas(ingrediente_id);"}	pcp_mrp_new_tables	zezolas27@gmail.com	\N	\N
20260401213235	{"-- PARTE 4: ESTOQUE INTELIGENTE\n\nCREATE TABLE IF NOT EXISTS public.estoque_parametros (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id) ON DELETE CASCADE,\n    ingrediente_id UUID NOT NULL REFERENCES public.ingredientes(id) ON DELETE CASCADE,\n    classificacao_abc VARCHAR(1) CHECK (classificacao_abc IN ('A', 'B', 'C')),\n    classificacao_xyz VARCHAR(1) CHECK (classificacao_xyz IN ('X', 'Y', 'Z')),\n    valor_consumo_periodo NUMERIC(12,2) DEFAULT 0,\n    consumo_medio_diario_g NUMERIC(12,3) DEFAULT 0,\n    desvio_padrao_consumo_g NUMERIC(12,3) DEFAULT 0,\n    coeficiente_variacao NUMERIC(6,4) DEFAULT 0,\n    dias_analisados INTEGER DEFAULT 0,\n    lead_time_medio_dias INTEGER DEFAULT 3,\n    lead_time_desvio_dias NUMERIC(6,2) DEFAULT 1,\n    estoque_seguranca_g NUMERIC(14,3) DEFAULT 0,\n    ponto_pedido_g NUMERIC(14,3) DEFAULT 0,\n    par_level_g NUMERIC(14,3) DEFAULT 0,\n    lote_economico_g NUMERIC(14,3) DEFAULT 0,\n    shelf_life_dias INTEGER,\n    frequencia_ideal_compra_dias INTEGER,\n    z_score_aplicado NUMERIC(4,2) DEFAULT 1.28,\n    nivel_servico_pct NUMERIC(5,2) DEFAULT 90.00,\n    ultima_classificacao_em TIMESTAMPTZ,\n    notas TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    UNIQUE(unidade_id, ingrediente_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_estoque_params_unidade ON estoque_parametros(unidade_id);\nCREATE INDEX IF NOT EXISTS idx_estoque_params_abc ON estoque_parametros(classificacao_abc);\nCREATE INDEX IF NOT EXISTS idx_estoque_params_xyz ON estoque_parametros(classificacao_xyz);\n\n-- PARTE 5: PROCUREMENT\n\nCREATE TABLE IF NOT EXISTS public.compras_cotacoes (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id) ON DELETE CASCADE,\n    codigo VARCHAR(50) NOT NULL,\n    titulo TEXT,\n    fornecedor_id UUID REFERENCES public.fornecedores(id),\n    status VARCHAR(30) DEFAULT 'RASCUNHO' CHECK (status IN ('RASCUNHO', 'ENVIADA', 'RESPONDIDA', 'APROVADA', 'REJEITADA', 'CONVERTIDA')),\n    data_validade_cotacao DATE,\n    valor_total NUMERIC(12,2) DEFAULT 0,\n    observacoes TEXT,\n    mrp_periodo_id UUID REFERENCES public.pmp_periodos(id),\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    created_by UUID REFERENCES auth.users(id),\n    updated_at TIMESTAMPTZ DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_compras_cotacoes_unidade ON compras_cotacoes(unidade_id);\nCREATE INDEX IF NOT EXISTS idx_compras_cotacoes_status ON compras_cotacoes(status);\n\nCREATE TABLE IF NOT EXISTS public.compras_cotacoes_itens (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cotacao_id UUID NOT NULL REFERENCES public.compras_cotacoes(id) ON DELETE CASCADE,\n    ingrediente_id UUID REFERENCES public.ingredientes(id),\n    material_id UUID REFERENCES public.materiais(id),\n    mrp_ordem_id UUID REFERENCES public.mrp_ordens_planejadas(id),\n    quantidade_solicitada_g NUMERIC(12,3),\n    preco_unitario_cotado NUMERIC(10,4),\n    preco_total_cotado NUMERIC(12,2),\n    observacao TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_cotacoes_itens_cotacao ON compras_cotacoes_itens(cotacao_id);\n\nCREATE TABLE IF NOT EXISTS public.fornecedor_avaliacoes (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    fornecedor_id UUID NOT NULL REFERENCES public.fornecedores(id) ON DELETE CASCADE,\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id) ON DELETE CASCADE,\n    periodo_avaliacao VARCHAR(7) NOT NULL,\n    entregas_total INTEGER DEFAULT 0,\n    entregas_no_prazo INTEGER DEFAULT 0,\n    lead_time_real_medio NUMERIC(6,2),\n    taxa_conformidade NUMERIC(5,2),\n    taxa_pontualidade NUMERIC(5,2),\n    preco_competitividade NUMERIC(5,2),\n    score_geral NUMERIC(5,2),\n    observacoes TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    UNIQUE(fornecedor_id, unidade_id, periodo_avaliacao)\n);\n\nCREATE INDEX IF NOT EXISTS idx_fornecedor_aval_fornecedor ON fornecedor_avaliacoes(fornecedor_id);"}	pcp_mrp_estoque_procurement	zezolas27@gmail.com	\N	\N
20260401213257	{"-- PARTE 6: RLS POLICIES\n\nALTER TABLE public.pmp_periodos ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.pmp_demandas ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.mrp_necessidades ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.mrp_ordens_planejadas ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.estoque_parametros ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.compras_cotacoes ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.compras_cotacoes_itens ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.fornecedor_avaliacoes ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"pmp_periodos_unit_isolation\\" ON public.pmp_periodos\n    FOR ALL USING (\n        unidade_id IN (SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid())\n    );\n\nCREATE POLICY \\"pmp_demandas_unit_isolation\\" ON public.pmp_demandas\n    FOR ALL USING (\n        pmp_periodo_id IN (\n            SELECT id FROM public.pmp_periodos WHERE unidade_id IN (\n                SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\n            )\n        )\n    );\n\nCREATE POLICY \\"mrp_necessidades_unit_isolation\\" ON public.mrp_necessidades\n    FOR ALL USING (\n        pmp_periodo_id IN (\n            SELECT id FROM public.pmp_periodos WHERE unidade_id IN (\n                SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\n            )\n        )\n    );\n\nCREATE POLICY \\"mrp_ordens_unit_isolation\\" ON public.mrp_ordens_planejadas\n    FOR ALL USING (\n        mrp_necessidade_id IN (\n            SELECT id FROM public.mrp_necessidades WHERE pmp_periodo_id IN (\n                SELECT id FROM public.pmp_periodos WHERE unidade_id IN (\n                    SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\n                )\n            )\n        )\n    );\n\nCREATE POLICY \\"estoque_params_unit_isolation\\" ON public.estoque_parametros\n    FOR ALL USING (\n        unidade_id IN (SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid())\n    );\n\nCREATE POLICY \\"cotacoes_unit_isolation\\" ON public.compras_cotacoes\n    FOR ALL USING (\n        unidade_id IN (SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid())\n    );\n\nCREATE POLICY \\"cotacoes_itens_unit_isolation\\" ON public.compras_cotacoes_itens\n    FOR ALL USING (\n        cotacao_id IN (\n            SELECT id FROM public.compras_cotacoes WHERE unidade_id IN (\n                SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid()\n            )\n        )\n    );\n\nCREATE POLICY \\"fornecedor_aval_unit_isolation\\" ON public.fornecedor_avaliacoes\n    FOR ALL USING (\n        unidade_id IN (SELECT unidade_id FROM public.app_user_memberships WHERE usuario_id = auth.uid())\n    );\n\n-- PARTE 7: FK CRUZADAS\n\nDO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM information_schema.table_constraints\n        WHERE constraint_name = 'producao_ordens_pmp_periodo_id_fkey'\n    ) THEN\n        ALTER TABLE public.producao_ordens\n        ADD CONSTRAINT producao_ordens_pmp_periodo_id_fkey\n        FOREIGN KEY (pmp_periodo_id) REFERENCES public.pmp_periodos(id);\n    END IF;\nEND $$;\n\nDO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM information_schema.table_constraints\n        WHERE constraint_name = 'producao_requisicoes_mrp_necessidade_id_fkey'\n    ) THEN\n        ALTER TABLE public.producao_requisicoes\n        ADD CONSTRAINT producao_requisicoes_mrp_necessidade_id_fkey\n        FOREIGN KEY (mrp_necessidade_id) REFERENCES public.mrp_necessidades(id);\n    END IF;\nEND $$;\n\nDO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM information_schema.table_constraints\n        WHERE constraint_name = 'mrp_ordens_convertida_cotacao_fkey'\n    ) THEN\n        ALTER TABLE public.mrp_ordens_planejadas\n        ADD CONSTRAINT mrp_ordens_convertida_cotacao_fkey\n        FOREIGN KEY (convertida_cotacao_id) REFERENCES public.compras_cotacoes(id);\n    END IF;\nEND $$;"}	pcp_mrp_rls_and_fks	zezolas27@gmail.com	\N	\N
20260401233926	{"-- 1. Habilitar pg_net e preparar schemas\nCREATE EXTENSION IF NOT EXISTS pg_net;\n\n-- 2. Restrições de Unicidade para suportar Sync (UPSERT)\nALTER TABLE public.pmp_periodos \nADD CONSTRAINT uq_pmp_periodo_unidade_datas UNIQUE (unidade_id, data_inicio, data_fim);\n\nALTER TABLE public.pmp_demandas \nADD CONSTRAINT uq_pmp_demanda_origem UNIQUE (origem_id);\n\n-- 3. Função de Sincronização UAN -> PMP\nCREATE OR REPLACE FUNCTION public.fn_sync_uan_cardapio_pmp()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_unidade_id UUID;\n    v_periodo_id UUID;\n    v_mes_ano TEXT;\n    v_data_inicio DATE;\n    v_data_fim DATE;\n    v_comensais INTEGER;\nBEGIN\n    -- Obter unidade e comensais do cardápio pai\n    SELECT cliente_id, comensais_estimados_dia INTO v_unidade_id, v_comensais\n    FROM public.cardapios_uan \n    WHERE id = NEW.cardapio_id;\n\n    v_mes_ano := to_char(NEW.data_consumo, 'YYYY-MM');\n    v_data_inicio := date_trunc('month', NEW.data_consumo)::date;\n    v_data_fim := (date_trunc('month', NEW.data_consumo) + interval '1 month' - interval '1 day')::date;\n\n    -- Upsert do Mes no PMP\n    INSERT INTO public.pmp_periodos (unidade_id, nome, tipo, data_inicio, data_fim, status)\n    VALUES (v_unidade_id, 'Planejamento ' || v_mes_ano, 'MENSAL', v_data_inicio, v_data_fim, 'APROVADO')\n    ON CONFLICT (unidade_id, data_inicio, data_fim) DO UPDATE SET updated_at = now()\n    RETURNING id INTO v_periodo_id;\n\n    -- Upsert da Demanda\n    INSERT INTO public.pmp_demandas (pmp_periodo_id, origem_tipo, origem_id, ficha_uan_id, data_necessidade, quantidade_planejada, unidade_medida)\n    VALUES (v_periodo_id, 'CARDAPIO_UAN', NEW.id, NEW.ficha_uan_id, NEW.data_consumo, (v_comensais * NEW.fator_multiplicador), 'UN')\n    ON CONFLICT (origem_id) DO UPDATE SET \n        quantidade_planejada = EXCLUDED.quantidade_planejada,\n        data_necessidade = EXCLUDED.data_necessidade,\n        ficha_uan_id = EXCLUDED.ficha_uan_id;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 4. Função de Sincronização Produção (Indústria) -> PMP\nCREATE OR REPLACE FUNCTION public.fn_sync_producao_pmp()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_unidade_id UUID;\n    v_periodo_id UUID;\n    v_mes_ano TEXT;\n    v_data_inicio DATE;\n    v_data_fim DATE;\n    v_data_necessidade DATE;\nBEGIN\n    -- Obter unidade e data da ordem de produção\n    SELECT unidade_id, data_prevista INTO v_unidade_id, v_data_necessidade\n    FROM public.producao_ordens \n    WHERE id = NEW.ordem_id;\n\n    IF v_data_necessidade IS NULL THEN \n        v_data_necessidade := CURRENT_DATE;\n    END IF;\n\n    v_mes_ano := to_char(v_data_necessidade, 'YYYY-MM');\n    v_data_inicio := date_trunc('month', v_data_necessidade)::date;\n    v_data_fim := (date_trunc('month', v_data_necessidade) + interval '1 month' - interval '1 day')::date;\n\n    -- Upsert do Mes no PMP\n    INSERT INTO public.pmp_periodos (unidade_id, nome, tipo, data_inicio, data_fim, status)\n    VALUES (v_unidade_id, 'Planejamento ' || v_mes_ano, 'MENSAL', v_data_inicio, v_data_fim, 'APROVADO')\n    ON CONFLICT (unidade_id, data_inicio, data_fim) DO UPDATE SET updated_at = now()\n    RETURNING id INTO v_periodo_id;\n\n    -- Upsert da Demanda (PCP usa receita_id)\n    INSERT INTO public.pmp_demandas (pmp_periodo_id, origem_tipo, origem_id, receita_id, data_necessidade, quantidade_planejada, unidade_medida)\n    VALUES (v_periodo_id, 'ORDEM_SERVICO', NEW.id, NEW.receita_id, v_data_necessidade, NEW.quantidade, 'UN')\n    ON CONFLICT (origem_id) DO UPDATE SET \n        quantidade_planejada = EXCLUDED.quantidade_planejada,\n        data_necessidade = EXCLUDED.data_necessidade,\n        receita_id = EXCLUDED.receita_id;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 5. Triggers de Sincronização\nDROP TRIGGER IF EXISTS tr_sync_uan_cardapio ON public.cardapio_dias_uan;\nCREATE TRIGGER tr_sync_uan_cardapio\nAFTER INSERT OR UPDATE ON public.cardapio_dias_uan\nFOR EACH ROW EXECUTE FUNCTION public.fn_sync_uan_cardapio_pmp();\n\nDROP TRIGGER IF EXISTS tr_sync_producao ON public.producao_ordens_itens;\nCREATE TRIGGER tr_sync_producao\nAFTER INSERT OR UPDATE ON public.producao_ordens_itens\nFOR EACH ROW EXECUTE FUNCTION public.fn_sync_producao_pmp();\n\n-- 6. Trigger Reativo MRP (Dispara Edge Function via pg_net)\nCREATE OR REPLACE FUNCTION public.fn_trigger_mrp_engine()\nRETURNS TRIGGER AS $$\nBEGIN\n    PERFORM\n      net.http_post(\n        url := 'https://ircjgepumexoqslljtql.supabase.co/functions/v1/executar-mrp',\n        headers := jsonb_build_object(\n          'Content-Type', 'application/json',\n          'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImlyY2pnZXB1bWV4b3FzbGxqdHFsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjYwMTI4MjQsImV4cCI6MjA4MTU4ODgyNH0.TKkpCu6GUD9tpJdGPCMNJfaJnF14tpqxIzNDbxz_j4U'\n        ),\n        body := jsonb_build_object(\n          'unidade_id', (SELECT unidade_id FROM public.pmp_periodos WHERE id = NEW.pmp_periodo_id),\n          'periodo_id', NEW.pmp_periodo_id\n        )\n      );\n    \n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS tr_trigger_mrp ON public.pmp_demandas;\nCREATE TRIGGER tr_trigger_mrp\nAFTER INSERT OR UPDATE ON public.pmp_demandas\nFOR EACH ROW EXECUTE FUNCTION public.fn_trigger_mrp_engine();\n"}	automacao_mrp_v1	zezolas27@gmail.com	\N	\N
20260401235139	{"CREATE OR REPLACE FUNCTION public.fn_sync_producao_pmp()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_unidade_id UUID;\n    v_periodo_id UUID;\n    v_mes_ano TEXT;\n    v_data_inicio DATE;\n    v_data_fim DATE;\n    v_data_necessidade DATE;\nBEGIN\n    -- Obter unidade e data da ordem de produção\n    SELECT unidade_id, data_prevista INTO v_unidade_id, v_data_necessidade\n    FROM public.producao_ordens \n    WHERE id = NEW.ordem_id;\n\n    IF v_data_necessidade IS NULL THEN \n        v_data_necessidade := CURRENT_DATE;\n    END IF;\n\n    v_mes_ano := to_char(v_data_necessidade, 'YYYY-MM');\n    v_data_inicio := date_trunc('month', v_data_necessidade)::date;\n    v_data_fim := (date_trunc('month', v_data_necessidade) + interval '1 month' - interval '1 day')::date;\n\n    -- Upsert do Mes no PMP\n    -- Alterado para usar ON CONFLICT (unidade_id, data_inicio, data_fim) \n    -- Assumindo que existe uma constraint unique ou índice único para esses 3 campos.\n    INSERT INTO public.pmp_periodos (unidade_id, nome, tipo, data_inicio, data_fim, status)\n    VALUES (v_unidade_id, 'Planejamento ' || v_mes_ano, 'MENSAL', v_data_inicio, v_data_fim, 'APROVADO')\n    ON CONFLICT (unidade_id, data_inicio, data_fim) DO UPDATE SET updated_at = now()\n    RETURNING id INTO v_periodo_id;\n\n    -- Upsert da Demanda (PCP usa receita_id)\n    -- CORREÇÃO: NEW.quantidade -> NEW.quantidade_planejada\n    INSERT INTO public.pmp_demandas (pmp_periodo_id, origem_tipo, origem_id, receita_id, data_necessidade, quantidade_planejada, unidade_medida)\n    VALUES (v_periodo_id, 'ORDEM_SERVICO', NEW.id, NEW.receita_id, v_data_necessidade, NEW.quantidade_planejada, 'UN')\n    ON CONFLICT (origem_id) DO UPDATE SET \n        quantidade_planejada = EXCLUDED.quantidade_planejada,\n        data_necessidade = EXCLUDED.data_necessidade,\n        receita_id = EXCLUDED.receita_id;\n\n    RETURN NEW;\nEND;\n$function$;\n"}	fix_fn_sync_producao_pmp_column_name	zezolas27@gmail.com	\N	\N
20260402134817	{"-- Reversion SQL script\n-- Part 1: Remove extra columns from existing tables\nALTER TABLE public.ingredientes \nDROP COLUMN IF EXISTS shelf_life_dias,\nDROP COLUMN IF EXISTS temperatura_armazenamento;\n\nALTER TABLE public.producao_requisicoes\nDROP COLUMN IF EXISTS mrp_necessidade_id,\nDROP COLUMN IF EXISTS prioridade;\n\n-- Part 2: Drop extra tables (not in reference schema)\nDROP TABLE IF EXISTS public.mrp_ordens_planejadas CASCADE;\nDROP TABLE IF EXISTS public.fornecedor_avaliacoes CASCADE;\nDROP TABLE IF EXISTS public.mrp_necessidades CASCADE;\nDROP TABLE IF EXISTS public.compras_cotacoes CASCADE;\nDROP TABLE IF EXISTS public.estoque_parametros CASCADE;\nDROP TABLE IF EXISTS public.pmp_demandas CASCADE;\nDROP TABLE IF EXISTS public.pmp_periodos CASCADE;\nDROP TABLE IF EXISTS public.compras_cotacoes_itens CASCADE;\n\n-- Note: executre-mrp edge function cannot be deleted via SQL/MCP, \n-- but its logic is now detached from the core schema.\n"}	revert_to_reference_state	zezolas27@gmail.com	\N	\N
20260402135637	{"-- Final alignment to schemagestão.sql\nALTER TABLE public.producao_ordens \nDROP COLUMN IF EXISTS origem_tipo,\nDROP COLUMN IF EXISTS pmp_periodo_id;\n\n-- Ensure constraints match (though MCP list_tables doesn't show all, we ensure columns are clean)\n"}	final_alignment_to_reference	zezolas27@gmail.com	\N	\N
20260403014500	{"ALTER TABLE public.fichas_tecnicas_uan ADD COLUMN IF NOT EXISTS refeicoes text[] DEFAULT '{}'::text[];"}	add_refeicoes_to_fichas_uan	zezolas27@gmail.com	\N	\N
20260403142917	{"CREATE OR REPLACE FUNCTION public.fn_gerar_audit_log()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    IF (TG_OP = 'DELETE') THEN\n        INSERT INTO public.audit_logs_sistema (tabela, registro_id, acao, usuario_id, dados_antigos)\n        VALUES (TG_TABLE_NAME::text, OLD.id, 'DELETE', auth.uid(), to_jsonb(OLD));\n        RETURN OLD;\n    ELSIF (TG_OP = 'UPDATE') THEN\n        INSERT INTO public.audit_logs_sistema (tabela, registro_id, acao, usuario_id, dados_antigos, dados_novos)\n        VALUES (TG_TABLE_NAME::text, NEW.id, 'UPDATE', auth.uid(), to_jsonb(OLD), to_jsonb(NEW));\n        RETURN NEW;\n    ELSIF (TG_OP = 'INSERT') THEN\n        INSERT INTO public.audit_logs_sistema (tabela, registro_id, acao, usuario_id, dados_novos)\n        VALUES (TG_TABLE_NAME::text, NEW.id, 'INSERT', auth.uid(), to_jsonb(NEW));\n        RETURN NEW;\n    END IF;\n    RETURN NULL;\nEND;\n$function$;"}	fix_audit_logs_sistema_function	zezolas27@gmail.com	\N	\N
20260403144718	{"-- Add margin for industrial production orders\nALTER TABLE public.producao_ordens \nADD COLUMN IF NOT EXISTS margem_erro_compras numeric DEFAULT 0;\n\n-- Add global margin for UAN cycles\nALTER TABLE public.cardapios_uan \nADD COLUMN IF NOT EXISTS margem_erro_compras_global numeric DEFAULT 0;\n\n-- Create table for per-ingredient margins in UAN cycles\nCREATE TABLE IF NOT EXISTS public.uan_cardapio_insumos_config (\n    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,\n    cardapio_id uuid REFERENCES public.cardapios_uan(id) ON DELETE CASCADE,\n    ingrediente_id uuid REFERENCES public.ingredientes(id) ON DELETE CASCADE,\n    margem_erro numeric DEFAULT 0,\n    created_at timestamp with time zone DEFAULT now(),\n    updated_at timestamp with time zone DEFAULT now(),\n    UNIQUE(cardapio_id, ingrediente_id)\n);\n\n-- Enable RLS for the new table\nALTER TABLE public.uan_cardapio_insumos_config ENABLE ROW LEVEL SECURITY;\n\n-- Simple permissive policy for now (since users already have access to cardapios and ingredientes)\nCREATE POLICY \\"Permitir tudo para usuários autenticados\\" ON public.uan_cardapio_insumos_config\n    FOR ALL USING (auth.role() = 'authenticated');\n"}	add_compras_margins_config_table	zezolas27@gmail.com	\N	\N
20260403151844	{"-- 1. producao_requisicoes: Add procurement status\nALTER TABLE public.producao_requisicoes \nADD COLUMN IF NOT EXISTS status_compras VARCHAR(50) DEFAULT 'PENDENTE',\nADD COLUMN IF NOT EXISTS comprado_em TIMESTAMP WITH TIME ZONE;\n\n-- 2. uan_compras_monitoramento: Tracking for UAN cycle purchases\nCREATE TABLE IF NOT EXISTS public.uan_compras_monitoramento (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cardapio_id UUID NOT NULL REFERENCES public.cardapios_uan(id) ON DELETE CASCADE,\n    ingrediente_id UUID NOT NULL REFERENCES public.ingredientes(id) ON DELETE CASCADE,\n    quantidade_comprada NUMERIC(10,3) NOT NULL,\n    status_compras VARCHAR(50) DEFAULT 'PENDENTE',\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    UNIQUE(cardapio_id, ingrediente_id)\n);\n\n-- Enable RLS for monitoring table\nALTER TABLE public.uan_compras_monitoramento ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"Acesso usuários autenticados uan_compras_monitoramento\\" \nON public.uan_compras_monitoramento FOR ALL\nUSING (auth.uid() IS NOT NULL);\n\n-- Add Index for performance\nCREATE INDEX IF NOT EXISTS idx_uan_compras_monit_cardapio_id ON uan_compras_monitoramento(cardapio_id);\n"}	add_procurement_tracking	zezolas27@gmail.com	\N	\N
20260404204039	{"-- Adicionar colunas para portfólio hierárquico\nALTER TABLE public.fornecedores \nADD COLUMN IF NOT EXISTS grupos_fornecidos uuid[] DEFAULT '{}',\nADD COLUMN IF NOT EXISTS itens_fornecidos uuid[] DEFAULT '{}';\n\n-- Criar índices GIN para busca eficiente nestas colunas (útil para matriz de Kraljic futuramente)\nCREATE INDEX IF NOT EXISTS idx_fornecedores_grupos ON public.fornecedores USING GIN (grupos_fornecidos);\nCREATE INDEX IF NOT EXISTS idx_fornecedores_itens ON public.fornecedores USING GIN (itens_fornecidos);\n\n-- Comentários para documentação do esquema\nCOMMENT ON COLUMN public.fornecedores.grupos_fornecidos IS 'IDs de grupos de ingredientes que este fornecedor atende';\nCOMMENT ON COLUMN public.fornecedores.itens_fornecidos IS 'IDs de itens específicos de ingredientes que este fornecedor atende';"}	fornecedores_portfolio_hierarquico_20260404204100	zezolas27@gmail.com	\N	\N
20260404212119	{"CREATE TABLE IF NOT EXISTS public.compras_orcamentos (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    unidade_id UUID NOT NULL REFERENCES public.cliente_unidades(id) ON DELETE CASCADE,\n    fornecedor_id UUID NOT NULL REFERENCES public.fornecedores(id) ON DELETE CASCADE,\n    ingrediente_id UUID NOT NULL REFERENCES public.ingredientes(id) ON DELETE CASCADE,\n    data_orcamento DATE NOT NULL DEFAULT CURRENT_DATE,\n    is_embalagem BOOLEAN DEFAULT FALSE,\n    unidades_por_embalagem NUMERIC,\n    peso_volume_por_unidade NUMERIC,\n    preco_embalagem NUMERIC,\n    preco_por_kg_l NUMERIC NOT NULL,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nALTER TABLE public.compras_orcamentos ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS \\"Orcamentos Isolados por Cliente\\" ON public.compras_orcamentos;\nCREATE POLICY \\"Orcamentos Isolados por Cliente\\" ON public.compras_orcamentos\n    FOR ALL USING (\n        cliente_id IN ( \n            SELECT r.cliente_id \n            FROM public.app_roles r\n            JOIN public.app_user_memberships m ON m.role_id = r.id\n            WHERE m.usuario_id = auth.uid()\n        )\n    );\n"}	create_compras_orcamentos_final_v2	zezolas27@gmail.com	\N	\N
20260405134544	{"-- 1. ADICIONANDO LEAD TIME NO FORNECEDOR (Opção A)\nALTER TABLE public.fornecedores \nADD COLUMN IF NOT EXISTS lead_time_dias NUMERIC DEFAULT 3;\n\nCOMMENT ON COLUMN public.fornecedores.lead_time_dias IS 'Tempo padronizado em dias que o fornecedor leva para entregar o pedido (Lead Time global)';\n\n-- 2. ADICIONANDO PARAMETRIZAÇÃO DE ESTOQUE NOS INGREDIENTES\nALTER TABLE public.ingredientes\nADD COLUMN IF NOT EXISTS uso_medio_diario NUMERIC DEFAULT 0,\nADD COLUMN IF NOT EXISTS estoque_seguranca_perc INTEGER DEFAULT 20;\n\nCOMMENT ON COLUMN public.ingredientes.uso_medio_diario IS 'Consumo médio diário (ADU) do insumo (kg/l/und). Inicialmente manual, depois automatizado pelo PDV/Fichas.';\nCOMMENT ON COLUMN public.ingredientes.estoque_seguranca_perc IS 'Porcentagem de margem de segurança (Safety Stock) aplicada sobre a demanda do Lead Time.';\n\n-- 3. CRIANDO VIEW DE CONTRATOS/CUSTOS PARA A MATRIZ DE KRALJIC\nCREATE OR REPLACE VIEW gerencial_compras_kraljic_base AS\nWITH fornecedores_por_item AS (\n    SELECT \n        o.ingrediente_id,\n        MIN(o.preco_por_kg_l) AS menor_preco,\n        COUNT(DISTINCT o.fornecedor_id) AS qtd_fornecedores,\n        MAX(f.lead_time_dias) AS lead_time_max\n    FROM compras_orcamentos o\n    JOIN fornecedores f ON o.fornecedor_id = f.id\n    GROUP BY o.ingrediente_id\n),\nestoque_por_item AS (\n    SELECT \n        ingrediente_id,\n        SUM(quantidade_atual_g_ml) AS total_estoque\n    FROM lotes_estoque\n    WHERE quantidade_atual_g_ml > 0\n    GROUP BY ingrediente_id\n)\nSELECT \n    i.id AS ingrediente_id,\n    i.nome AS ingrediente_nome,\n    i.categoria_produto_id,\n    i.uso_medio_diario,\n    i.estoque_seguranca_perc,\n    COALESCE(e.total_estoque, 0) AS estoque_atual,\n    COALESCE(f_info.menor_preco, 0) AS custo_referencia,\n    COALESCE(f_info.qtd_fornecedores, 0) AS fornecedores_ativos,\n    COALESCE(f_info.lead_time_max, 3) AS lead_time_considerado\nFROM ingredientes i\nLEFT JOIN fornecedores_por_item f_info ON i.id = f_info.ingrediente_id\nLEFT JOIN estoque_por_item e ON i.id = e.ingrediente_id;"}	20260405100000_modulo_inteligencia_estoque	zezolas27@gmail.com	\N	\N
20260405135859	{"DROP VIEW IF EXISTS gerencial_compras_kraljic_base;\n\nCREATE OR REPLACE VIEW gerencial_compras_kraljic_base AS\nWITH fornecedores_por_item AS (\n    SELECT \n        o.ingrediente_id,\n        MIN(o.preco_por_kg_l) AS menor_preco,\n        COUNT(DISTINCT o.fornecedor_id) AS qtd_fornecedores,\n        MAX(f.lead_time_dias) AS lead_time_max\n    FROM compras_orcamentos o\n    JOIN fornecedores f ON o.fornecedor_id = f.id\n    GROUP BY o.ingrediente_id\n),\nestoque_por_item AS (\n    SELECT \n        ingrediente_id,\n        SUM(quantidade_atual_g_ml) AS total_estoque\n    FROM lotes_estoque\n    WHERE quantidade_atual_g_ml > 0\n    GROUP BY ingrediente_id\n),\n-- MRP 1: Demanda via CARDÁPIOS UAN\ndemanda_cardapios AS (\n    SELECT \n        comp.ingrediente_id,\n        SUM(comp.peso_bruto_g * COALESCE(dias.fator_multiplicador, 1) * COALESCE(card.comensais_estimados_dia, 1) / 1000.0) AS demanda_mrp_kg\n    FROM cardapio_dias_uan dias\n    JOIN cardapios_uan card ON dias.cardapio_id = card.id\n    JOIN composicao_fichas_uan comp ON dias.ficha_uan_id = comp.ficha_uan_id\n    WHERE dias.data_consumo >= CURRENT_DATE\n    -- Consideramos apenas a demanda que recai na janela de cobertura do próprio ciclo\n    GROUP BY comp.ingrediente_id\n),\n-- MRP 2: Demanda via ORDENS DE PRODUÇÃO\ndemanda_producao AS (\n    SELECT \n        comp.ingrediente_id,\n        SUM(comp.peso_bruto_g * COALESCE(itens.quantidade_planejada, 1) / 1000.0) AS demanda_mrp_kg\n    FROM producao_ordens_itens itens\n    JOIN producao_ordens ordem ON itens.ordem_id = ordem.id\n    JOIN composicao_fichas_uan comp ON itens.receita_id = comp.ficha_uan_id\n    WHERE ordem.data_prevista >= CURRENT_DATE\n    GROUP BY comp.ingrediente_id\n),\n-- UNIFICANDO MRP\ndemanda_unificada AS (\n    SELECT \n        ingrediente_id,\n        SUM(demanda_mrp_kg) AS programacao_futura_kg\n    FROM (\n        SELECT ingrediente_id, demanda_mrp_kg FROM demanda_cardapios\n        UNION ALL\n        SELECT ingrediente_id, demanda_mrp_kg FROM demanda_producao\n    ) AS u\n    GROUP BY ingrediente_id\n)\n\nSELECT \n    i.id AS ingrediente_id,\n    i.nome AS ingrediente_nome,\n    i.categoria_produto_id,\n    i.uso_medio_diario,\n    i.estoque_seguranca_perc,\n    COALESCE(e.total_estoque, 0) AS estoque_atual,\n    COALESCE(f_info.menor_preco, 0) AS custo_referencia,\n    COALESCE(f_info.qtd_fornecedores, 0) AS fornecedores_ativos,\n    COALESCE(f_info.lead_time_max, 3) AS lead_time_considerado,\n    COALESCE(mrp.programacao_futura_kg, 0) AS demanda_programada_kg\nFROM ingredientes i\nLEFT JOIN fornecedores_por_item f_info ON i.id = f_info.ingrediente_id\nLEFT JOIN estoque_por_item e ON i.id = e.ingrediente_id\nLEFT JOIN demanda_unificada mrp ON i.id = mrp.ingrediente_id;"}	20260405103000_update_kraljic_view_mrp	zezolas27@gmail.com	\N	\N
