20260408002136	{"-- Adiciona coluna deleted_at para suporte a Soft Delete (GxP Compliance)\nALTER TABLE checklist_auditorias ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;\nALTER TABLE checklist_modelos ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;\nALTER TABLE checklist_secoes ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;\nALTER TABLE checklist_itens ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;\nALTER TABLE checklist_respostas ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;\nALTER TABLE cliente_controle_temperatura ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;\n"}	add_deleted_at_quality	zezolas27@gmail.com	\N	\N
20260408020901	{"ALTER TABLE checklist_itens ADD COLUMN IF NOT EXISTS classificacao text DEFAULT 'NECESSARIO';\nALTER TABLE checklist_itens ADD COLUMN IF NOT EXISTS peso integer DEFAULT 3;\n\n-- Atualizar itens existentes com palavras-chave críticas\nUPDATE checklist_itens SET classificacao = 'IMPRESCINDIVEL', peso = 10 \nWHERE texto_pergunta ILIKE '%temperatura%' \n   OR texto_pergunta ILIKE '%validade%'\n   OR texto_pergunta ILIKE '%água%'\n   OR texto_pergunta ILIKE '%mãos%'\n   OR texto_pergunta ILIKE '%pragas%'\n   OR texto_pergunta ILIKE '%lixo%';\n\n-- Itens de organização (Recomendável)\nUPDATE checklist_itens SET classificacao = 'RECOMENDAVEL', peso = 1\nWHERE texto_pergunta ILIKE '%pintura%' \n   OR texto_pergunta ILIKE '%estética%'\n   OR texto_pergunta ILIKE '%organização%'\n   OR texto_pergunta ILIKE '%uniforme%';"}	adicionar_pesos_checklist_itens	zezolas27@gmail.com	\N	\N
