20260409230941	{"-- Adicionar coluna ficha_uan_id na tabela de itens de produção para suportar o módulo UAN\nALTER TABLE public.producao_ordens_itens \nADD COLUMN ficha_uan_id UUID REFERENCES public.fichas_tecnicas_uan(id);\n\n-- Tornar receita_id opcional (pode ser receita industrial ou ficha técnica UAN)\nALTER TABLE public.producao_ordens_itens \nALTER COLUMN receita_id DROP NOT NULL;\n\n-- Atualizar o RPC de geração de requisição para suportar UAN\nCREATE OR REPLACE FUNCTION public.gerar_requisicao_producao(p_ordem_id uuid)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- 1. Limpar requisições existentes (Apenas se a ordem estiver PLANEJADA)\n    DELETE FROM public.producao_requisicoes \n    WHERE ordem_id = p_ordem_id \n    AND status = 'PENDENTE';\n\n    -- 2. Gerar para Receitas Industriais (Composição padrão)\n    INSERT INTO public.producao_requisicoes (ordem_id, ingrediente_id, qtd_necessaria_g, status)\n    SELECT \n        p_ordem_id,\n        cr.item_id as ingrediente_id,\n        SUM(poi.quantidade_planejada * cr.peso_bruto_g) as qtd_total,\n        'PENDENTE'\n    FROM public.producao_ordens_itens poi\n    JOIN public.composicao_receitas cr ON cr.receita_id = poi.receita_id\n    WHERE poi.producao_ordem_id = p_ordem_id\n    AND poi.receita_id IS NOT NULL\n    GROUP BY p_ordem_id, cr.item_id;\n\n    -- 3. Gerar para Fichas Técnicas UAN\n    INSERT INTO public.producao_requisicoes (ordem_id, ingrediente_id, qtd_necessaria_g, status)\n    SELECT \n        p_ordem_id,\n        cfu.ingrediente_id,\n        -- Na UAN, a ficha técnica geralmente é dimensionada para X porções.\n        -- Peso Bruto total = (Qtd Desejada / Rendimento Ficha) * Peso Bruto Item\n        SUM((poi.quantidade_planejada / NULLIF(ftu.rendimento_porcoes, 0)) * cfu.peso_bruto_g) as qtd_total,\n        'PENDENTE'\n    FROM public.producao_ordens_itens poi\n    JOIN public.fichas_tecnicas_uan ftu ON ftu.id = poi.ficha_uan_id\n    JOIN public.composicao_fichas_uan cfu ON cfu.ficha_uan_id = poi.ficha_uan_id\n    WHERE poi.producao_ordem_id = p_ordem_id\n    AND poi.ficha_uan_id IS NOT NULL\n    GROUP BY p_ordem_id, cfu.ingrediente_id;\n\nEND;\n$function$;"}	add_ficha_uan_id_to_producao_items	zezolas27@gmail.com	\N	\N
20260416171155	{"-- Adicionar colunas na tabela de clientes\nALTER TABLE clientes ADD COLUMN IF NOT EXISTS endereco_completo TEXT;\nALTER TABLE clientes ADD COLUMN IF NOT EXISTS cep TEXT;\nALTER TABLE clientes ADD COLUMN IF NOT EXISTS cnaes JSONB DEFAULT '[]'::jsonb;\n\n-- Adicionar colunas na tabela de unidades de clientes (filiais)\nALTER TABLE cliente_unidades ADD COLUMN IF NOT EXISTS cep TEXT;\nALTER TABLE cliente_unidades ADD COLUMN IF NOT EXISTS cnaes JSONB DEFAULT '[]'::jsonb;\n\n-- Comentários para documentação\nCOMMENT ON COLUMN clientes.cnaes IS 'Lista de CNAEs (Principal + Secundários) capturados via Brasil API';\nCOMMENT ON COLUMN cliente_unidades.cnaes IS 'Lista de CNAEs da Unidade específica capturados via Brasil API';\n"}	add_address_and_multi_cnae_to_clients	zezolas27@gmail.com	\N	\N
20260409231205	{"-- Atualizar a função gerar_requisicao_producao para suportar Fichas Técnicas UAN\nCREATE OR REPLACE FUNCTION public.gerar_requisicao_producao(p_ordem_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_item RECORD;\nBEGIN\n    -- Limpar requisições existentes para esta ordem\n    DELETE FROM public.producao_requisicoes WHERE ordem_id = p_ordem_id;\n\n    -- 1. Processar Receitas Industriais (receita_id)\n    FOR v_item IN \n        SELECT \n            poi.receita_id,\n            poi.quantidade_planejada,\n            poi.setor_producao_id\n        FROM public.producao_ordens_itens poi\n        WHERE poi.ordem_id = p_ordem_id AND poi.receita_id IS NOT NULL\n    LOOP\n        INSERT INTO public.producao_requisicoes (\n            ordem_id,\n            ingrediente_id,\n            qtd_necessaria_g,\n            status\n        )\n        SELECT \n            p_ordem_id,\n            cr.item_id,\n            (v_item.quantidade_planejada / r.rendimento_total_g) * cr.peso_bruto_g,\n            'PENDENTE'\n        FROM public.composicao_receitas cr\n        JOIN public.receitas r ON r.id = cr.receita_id\n        WHERE cr.receita_id = v_item.receita_id AND cr.item_type = 'ingrediente';\n    END LOOP;\n\n    -- 2. Processar Fichas Técnicas UAN (ficha_uan_id)\n    FOR v_item IN \n        SELECT \n            poi.ficha_uan_id,\n            poi.quantidade_planejada,\n            poi.setor_producao_id\n        FROM public.producao_ordens_itens poi\n        WHERE poi.ordem_id = p_ordem_id AND poi.ficha_uan_id IS NOT NULL\n    LOOP\n        INSERT INTO public.producao_requisicoes (\n            ordem_id,\n            ingrediente_id,\n            qtd_necessaria_g,\n            status\n        )\n        SELECT \n            p_ordem_id,\n            cfu.ingrediente_id,\n            (v_item.quantidade_planejada / NULLIF(ftu.rendimento_porcoes, 0)) * cfu.peso_bruto_g,\n            'PENDENTE'\n        FROM public.composicao_fichas_uan cfu\n        JOIN public.fichas_tecnicas_uan ftu ON ftu.id = cfu.ficha_uan_id\n        WHERE cfu.ficha_uan_id = v_item.ficha_uan_id;\n    END LOOP;\n\nEND;\n$function$;\n"}	update_gerar_requisicao_producao_for_uan	zezolas27@gmail.com	\N	\N
