20260414141208	{"-- Adição de campos para Preparo e Reconstituição (RDC 429)\nALTER TABLE receitas ADD COLUMN IF NOT EXISTS is_preparo BOOLEAN DEFAULT false;\nALTER TABLE receitas ADD COLUMN IF NOT EXISTS rendimento_preparado_g NUMERIC;\n\n-- Adição de campo para diferenciar itens de preparo (ex: água adicionada pelo consumidor)\nALTER TABLE composicao_receitas ADD COLUMN IF NOT EXISTS is_preparation_only BOOLEAN DEFAULT false;\n\n-- Adição de campos granulares para aditivos críticos (RDC 727)\nALTER TABLE ingredientes ADD COLUMN IF NOT EXISTS is_tartrazina BOOLEAN DEFAULT false;\nALTER TABLE ingredientes ADD COLUMN IF NOT EXISTS is_aspartame BOOLEAN DEFAULT false;\nALTER TABLE ingredientes ADD COLUMN IF NOT EXISTS is_sunset_yellow BOOLEAN DEFAULT false;\n\n-- Comentários para documentação do schema\nCOMMENT ON COLUMN receitas.is_preparo IS 'Indica se o produto requer preparo/reconstituição para consumo.';\nCOMMENT ON COLUMN receitas.rendimento_preparado_g IS 'Peso final do produto após o preparo (usado para cálculo nutricional pronto para consumo).';\nCOMMENT ON COLUMN composicao_receitas.is_preparation_only IS 'Indica se o ingrediente é adicionado apenas no preparo final (não conta para custo de produção básica).';\n"}	add_compliance_fields_v3_fixed	zezolas27@gmail.com	\N	\N
20260414143526	{"ALTER TABLE public.receitas \nADD COLUMN IF NOT EXISTS is_sub_receita BOOLEAN DEFAULT FALSE,\nADD COLUMN IF NOT EXISTS instrucoes_preparo TEXT,\nADD COLUMN IF NOT EXISTS is_isento_nutricional BOOLEAN DEFAULT FALSE,\nADD COLUMN IF NOT EXISTS tipo_isencao TEXT;\n\nCOMMENT ON COLUMN public.receitas.is_sub_receita IS 'Indica se a receita é destinada a ser usada como ingrediente em outras receitas.';\nCOMMENT ON COLUMN public.receitas.instrucoes_preparo IS 'Instruções para o consumidor final preparar o alimento (obrigatório RDC 727).';\nCOMMENT ON COLUMN public.receitas.is_isento_nutricional IS 'Indica se o produto é isento de tabela nutricional completa (IN 75).';\nCOMMENT ON COLUMN public.receitas.tipo_isencao IS 'Tipo de isenção (ALCOOL, VINAGRE, CAFE, GELO, ESPECIARIA, etc).';"}	add_full_compliance_columns_to_receitas	zezolas27@gmail.com	\N	\N
