20260415201108	{"-- 1. Add missing strategic fields to operational table\nALTER TABLE public.checklist_execucoes \nADD COLUMN IF NOT EXISTS titulo text,\nADD COLUMN IF NOT EXISTS observacoes_gerais text,\nADD COLUMN IF NOT EXISTS cliente_id uuid REFERENCES public.clientes(id);\n\n-- 2. Migrate existing data from checklist_auditorias to checklist_execucoes\n-- We use Filial - Shopping (77ae5ae9-602d-4cbf-b708-9304616a33d4) as the target unit\nINSERT INTO public.checklist_execucoes (\n    id, \n    unidade_id, \n    modelo_id, \n    status, \n    data_inicio, \n    data_fim, \n    responsavel_id, \n    score_obtido, \n    titulo, \n    observacoes_gerais, \n    cliente_id\n)\nSELECT \n    id, \n    '77ae5ae9-602d-4cbf-b708-9304616a33d4', \n    modelo_id, \n    status, \n    data_inicio, \n    data_fim, \n    responsavel_id, \n    pontuacao_obtida, \n    titulo, \n    observacoes_gerais, \n    cliente_id\nFROM public.checklist_auditorias\nON CONFLICT (id) DO NOTHING;\n\n-- 3. Update checklist_respostas relationship\n-- First, drop the old constraint that points to checklist_auditorias\nALTER TABLE public.checklist_respostas\nDROP CONSTRAINT IF EXISTS checklist_respostas_auditoria_id_fkey;\n\n-- Then add the new one pointing to checklist_execucoes\nALTER TABLE public.checklist_respostas\nADD CONSTRAINT checklist_respostas_execucao_id_fkey \nFOREIGN KEY (auditoria_id) REFERENCES public.checklist_execucoes(id) ON DELETE CASCADE;\n\n-- 4. Rename old table to legacy instead of dropping (safety first)\nALTER TABLE public.checklist_auditorias RENAME TO checklist_auditorias_legacy;\n"}	consolidate_checklists_and_audits	zezolas27@gmail.com	\N	\N
